/**
 * lib/i18n.ts
 * ─────────────────────────────────────────────────────────────
 * Lightweight i18n system for desktools.run (Phase 1).
 * No external library — just a typed translation map.
 *
 * Usage:
 *   const { t } = useI18n();
 *   t("hero.title1")  →  "Fast Web Utilities"  (EN)
 *                     →  "빠른 웹 유틸리티"       (KO)
 *
 * Phase 2: Replace with next-intl for routing-based locale support.
 */

