    "exifRemover.guide.title": "Complete EXIF Metadata Cleaner Guide",
    "exifRemover.guide.aboutTitle": "What is Image EXIF Metadata?",
    "exifRemover.guide.aboutDesc": "EXIF (Exchangeable Image File Format) stores hidden metadata inside photos—such as your exact GPS location, camera serial number, lens parameters, and date/time of capture. Removing EXIF protects your privacy before sharing photos online.",
    "exifRemover.guide.howTitle": "How to Inspect & Remove EXIF Metadata",
    "exifRemover.guide.step1": "1. Drag & drop or upload your photo file.",
    "exifRemover.guide.step2": "2. Instantly review GPS coordinates, camera model, date/time, and metadata tags.",
    "exifRemover.guide.step3": "3. Click 'Remove All EXIF Metadata & Download Clean Image' to download a clean version.",
    "exifRemover.guide.faq1Q": "Is my photo uploaded to any server?",
    "exifRemover.guide.faq1A": "No! All EXIF parsing and image stripping run 100% inside your web browser JavaScript memory.",
    "exifRemover.guide.faq2Q": "Does removing EXIF metadata reduce photo quality?",
    "exifRemover.guide.faq2A": "No. The original pixel data is redrawn onto canvas at full resolution, keeping visual quality pristine.",

