    "pdfMerger.pages": "pages",
    "pdfMerger.guide.title": "Complete PDF Merger Guide",
    "pdfMerger.guide.badge": "100% Free & Local Processing",
    "pdfMerger.guide.aboutTitle": "What is the PDF Merger Tool?",
    "pdfMerger.guide.aboutDesc": "The PDF Merger allows you to combine multiple PDF documents into a single organized file directly inside your browser—100% free, lossless, and with zero server uploads.",
    "pdfMerger.guide.howTitle": "How to Combine PDF Files",
    "pdfMerger.guide.step1": "Drag & drop or select multiple PDF files to upload.",
    "pdfMerger.guide.step2": "Use the Up (▲) and Down (▼) buttons to arrange the files in your preferred sequence.",
    "pdfMerger.guide.step3": "Enter a custom output filename and click 'Merge PDF Files' to instantly download your combined document.",
    "pdfMerger.guide.featuresTitle": "Key Features & Highlights",
    "pdfMerger.guide.feat1Title": "100% Client-Side Privacy",
    "pdfMerger.guide.feat1Desc": "All PDF merging operations happen locally in your browser memory. Confidential documents and personal data never touch remote servers.",
    "pdfMerger.guide.feat2Title": "Lossless Vector & Text Preservation",
    "pdfMerger.guide.feat2Desc": "Preserves native text selection, searchability, embedded fonts, vector graphics, and hyperlinks without compression degradation.",
    "pdfMerger.guide.feat3Title": "Zero File Size or Count Limits",
    "pdfMerger.guide.feat3Desc": "No paywalls or daily conversion quotas. Merge as many PDF files and pages as your device's memory can handle.",
    "pdfMerger.guide.feat4Title": "Universal Cross-Platform Support",
    "pdfMerger.guide.feat4Desc": "Works instantly on Windows, macOS, Linux, iPad, and mobile browsers with zero software installation required.",
    "pdfMerger.guide.useCasesTitle": "Popular Use Cases & Scenarios",
    "pdfMerger.guide.uc1Title": "Business Proposals & Reports",
    "pdfMerger.guide.uc1Desc": "Consolidate separate project plans, meeting minutes, contracts, and quotes into one polished executive document.",
    "pdfMerger.guide.uc2Title": "Job Applications & Portfolios",
    "pdfMerger.guide.uc2Desc": "Combine your resume, cover letter, work samples, and credential scans into a single submission-ready PDF.",
    "pdfMerger.guide.uc3Title": "Academic Papers & Lecture Slides",
    "pdfMerger.guide.uc3Desc": "Organize multi-chapter lecture notes, research papers, and e-book materials into a unified study document.",
    "pdfMerger.guide.uc4Title": "Invoices & Expense Receipts",
    "pdfMerger.guide.uc4Desc": "Group monthly tax invoices and scanned expense receipts in chronological order for straightforward accounting filing.",
    "pdfMerger.guide.tipsTitle": "Pro Tips for Merging PDFs",
    "pdfMerger.guide.tip1": "For password-protected PDFs, unlock them first using our PDF Unlock tool before merging.",
    "pdfMerger.guide.tip2": "Different page sizes (A4, Letter, A3) and orientations (Portrait/Landscape) are preserved seamlessly.",
    "pdfMerger.guide.tip3": "Verify your cover, table of contents, and appendix order using the Up/Down buttons before downloading.",
    "pdfMerger.guide.faqTitle": "Frequently Asked Questions (FAQ)",
    "pdfMerger.guide.faq1Q": "Are my PDF files uploaded to or stored on any server?",
    "pdfMerger.guide.faq1A": "No. All PDF parsing and page merging operations happen 100% locally inside your browser memory using WebAssembly & pdf-lib. Nothing is sent to external servers.",
    "pdfMerger.guide.faq2Q": "Will the merged PDF keep searchable text, fonts, and hyperlinks?",
    "pdfMerger.guide.faq2A": "Yes! We merge native PDF binary objects rather than flattening to images. Text selection, searchability, embedded fonts, and URLs remain completely intact.",
    "pdfMerger.guide.faq3Q": "Is there a limit on how many PDFs or pages I can merge?",
    "pdfMerger.guide.faq3A": "There is no artificial limit. You can merge as many files as your computer or phone RAM allows.",
    "pdfMerger.guide.faq4Q": "Can I merge PDFs with different page sizes and orientations?",
    "pdfMerger.guide.faq4A": "Yes, each page maintains its unique dimensions (A4, US Letter, Custom) and portrait/landscape orientation in the merged file.",
    "pdfMerger.guide.faq5Q": "How do I reorder files before merging?",
    "pdfMerger.guide.faq5A": "After uploading, click the Up (▲) and Down (▼) buttons on each file card to arrange them in the exact order you want.",
    "pdfMerger.guide.faq6Q": "Does this work on mobile devices and tablets?",
    "pdfMerger.guide.faq6A": "Yes! The tool is fully responsive and compatible with mobile Chrome, Safari, and other modern mobile web browsers.",
