    "pdfSplit.guide.title": "Complete PDF Splitter & Page Extractor Guide",
    "pdfSplit.guide.badge": "100% Free & Local Processing",
    "pdfSplit.guide.aboutTitle": "What is the PDF Splitter Tool?",
    "pdfSplit.guide.aboutDesc": "The PDF Splitter allows you to extract specific pages, split documents into single-page PDFs, or extract custom page ranges 100% inside your browser using WebAssembly & pdf-lib—keeping your documents completely private.",
    "pdfSplit.guide.howTitle": "How to Split & Extract PDF Pages",
    "pdfSplit.guide.step1": "Drag & drop or select the PDF file you wish to split.",
    "pdfSplit.guide.step2": "Choose your split mode: Split All Pages, Custom Page Range (e.g. 1-3, 5), or Visual Thumbnail Selection.",
    "pdfSplit.guide.step3": "Click 'Split PDF Now' and download your split PDF documents instantly.",
    "pdfSplit.guide.featuresTitle": "Key Features & Highlights",
    "pdfSplit.guide.feat1Title": "100% Client-Side Privacy",
    "pdfSplit.guide.feat1Desc": "All page splitting runs locally in your browser memory. Confidential legal contracts and private data never touch remote servers.",
    "pdfSplit.guide.feat2Title": "Interactive Visual Thumbnails",
    "pdfSplit.guide.feat2Desc": "Preview every page rendered as a visual thumbnail and select exactly what you need with one-click checkboxes.",
    "pdfSplit.guide.feat3Title": "3 Flexible Splitting Modes",
    "pdfSplit.guide.feat3Desc": "Support for one-page-per-file bursts, complex range expressions (e.g. 1-3, 5, 8-12), and visual point-and-click extraction.",
    "pdfSplit.guide.feat4Title": "Lossless Vector & OCR Preservation",
    "pdfSplit.guide.feat4Desc": "Extracts native PDF binary objects so that searchable text, embedded fonts, vectors, and links remain crystal clear.",
    "pdfSplit.guide.useCasesTitle": "Popular Use Cases & Scenarios",
    "pdfSplit.guide.uc1Title": "Extract Specific Pages for Submission",
    "pdfSplit.guide.uc1Desc": "Pull out only the required signature pages, certificates, or annexes from a large multi-page contract.",
    "pdfSplit.guide.uc2Title": "Split Book Chapters & Research Papers",
    "pdfSplit.guide.uc2Desc": "Separate textbook chapters, thesis sections, or journal articles into standalone, easy-to-read study files.",
    "pdfSplit.guide.uc3Title": "Remove Confidential Internal Pages",
    "pdfSplit.guide.uc3Desc": "Exclude internal pricing sheets, personal identification, or sensitive notes before sharing documents externally.",
    "pdfSplit.guide.uc4Title": "Organize Multi-Page Scanned Batches",
    "pdfSplit.guide.uc4Desc": "Break down large multi-page office scans into clean individual single-page documents for archiving.",
    "pdfSplit.guide.tipsTitle": "Pro Tips for Splitting PDFs",
    "pdfSplit.guide.tip1": "Combine commas and hyphens like '1-3, 5, 8-12' in the range mode to extract multiple non-consecutive sections at once.",
    "pdfSplit.guide.tip2": "In Visual mode, use 'Select All' and uncheck the few pages you don't need for rapid exclusion.",
    "pdfSplit.guide.tip3": "Need to combine split pages with other files? Use our PDF Merger tool afterwards for seamless reorganization.",
    "pdfSplit.guide.faqTitle": "Frequently Asked Questions (FAQ)",
    "pdfSplit.guide.faq1Q": "Are my confidential PDF documents uploaded to any remote server?",
    "pdfSplit.guide.faq1A": "No! All PDF page extraction and splitting operations run 100% locally inside your browser memory using WebAssembly & pdf-lib.",
    "pdfSplit.guide.faq2Q": "Can I extract non-consecutive pages like 1, 4, 7-10?",
    "pdfSplit.guide.faq2A": "Yes! You can type any custom page range or visually click the thumbnail checkmarks to extract any exact combination of pages.",
    "pdfSplit.guide.faq3Q": "Will extracted PDF pages retain searchable text, fonts, and links?",
    "pdfSplit.guide.faq3A": "Yes! We extract raw PDF page objects rather than taking screenshot images, preserving all vector quality and text searchability.",
    "pdfSplit.guide.faq4Q": "Is there a page count or file size limit?",
    "pdfSplit.guide.faq4A": "No artificial limits! You can split PDF documents of any size as long as your device RAM can load it.",
    "pdfSplit.guide.faq5Q": "How are files named when using 'Split All Pages'?",
    "pdfSplit.guide.faq5A": "Each individual page is cleanly exported as '[filename]_page_1.pdf', '[filename]_page_2.pdf', and so on.",
    "pdfSplit.guide.faq6Q": "Can I split a password-protected PDF file?",
    "pdfSplit.guide.faq6A": "Please unlock the file first using our PDF Unlock tool before uploading it for splitting.",

