    "pdfCompress.guide.title": "Complete PDF Compression & Optimization Guide",
    "pdfCompress.guide.badge": "100% Free & Browser-Native",
    "pdfCompress.guide.aboutTitle": "What is the PDF Compressor Tool?",
    "pdfCompress.guide.aboutDesc": "The PDF Compressor optimizes internal object streams, metadata, and embedded elements directly in your browser memory (pdf-lib) with zero server uploads—delivering fast, private, and secure file size reduction.",
    "pdfCompress.guide.howTitle": "How to Compress & Reduce PDF Size",
    "pdfCompress.guide.step1": "Drag & drop or select the PDF file you want to compress.",
    "pdfCompress.guide.step2": "Choose your desired compression preset (Recommended, High Compression, or Low Compression).",
    "pdfCompress.guide.step3": "Click 'Compress PDF Now' and download your optimized document with instant size savings.",
    "pdfCompress.guide.featuresTitle": "Key Features & Advantages",
    "pdfCompress.guide.feat1Title": "100% Client-Side Privacy",
    "pdfCompress.guide.feat1Desc": "All document optimization executes locally in your browser memory. Confidential contracts and personal data never leave your device.",
    "pdfCompress.guide.feat2Title": "3 Tailored Compression Levels",
    "pdfCompress.guide.feat2Desc": "Select between Recommended (balanced), High (maximum savings), or Low (maximum visual quality) to match your exact needs.",
    "pdfCompress.guide.feat3Title": "Real-Time Size Savings Meter",
    "pdfCompress.guide.feat3Desc": "Immediately inspect original vs. compressed file size and percentage reduction before downloading.",
    "pdfCompress.guide.feat4Title": "Preserves Text & Vector Crispness",
    "pdfCompress.guide.feat4Desc": "Intelligently cleans redundant binary structures while keeping typography, vectors, and font outlines sharp and readable.",
    "pdfCompress.guide.useCasesTitle": "Popular Real-World Use Cases",
    "pdfCompress.guide.uc1Title": "Email Attachment Size Limits",
    "pdfCompress.guide.uc1Desc": "Shrink bulky PDFs below 10MB/25MB thresholds for smooth emailing via Gmail, Outlook, or corporate servers.",
    "pdfCompress.guide.uc2Title": "Government & Job Portals",
    "pdfCompress.guide.uc2Desc": "Meet strict upload size limits on official recruitment portals, university applications, and visa submission systems.",
    "pdfCompress.guide.uc3Title": "Save Mobile & Cloud Storage",
    "pdfCompress.guide.uc3Desc": "Save valuable gigabytes on Google Drive, Dropbox, iCloud, or local smartphone storage by optimizing document archives.",
    "pdfCompress.guide.uc4Title": "Lighten E-Books & Reports",
    "pdfCompress.guide.uc4Desc": "Compress extensive multi-page PDF presentations, annual reports, and study guides for faster mobile downloads.",
    "pdfCompress.guide.tipsTitle": "Pro Tips for PDF Compression",
    "pdfCompress.guide.tip1": "For standard office documents and reports, the 'Recommended' preset provides the best quality-to-size ratio.",
    "pdfCompress.guide.tip2": "If a PDF contains hundreds of high-resolution scanned pages, 'High Compression' yields dramatic size reductions.",
    "pdfCompress.guide.tip3": "Need to merge multiple documents before compressing? Combine them with our 'PDF Merger' first, then compress the final file.",
    "pdfCompress.guide.faqTitle": "Frequently Asked Questions (FAQ)",
    "pdfCompress.guide.faq1Q": "Are my uploaded PDF documents sent to any remote server?",
    "pdfCompress.guide.faq1A": "No! All compression and optimization runs 100% locally in your browser memory. Your files are never uploaded anywhere.",
    "pdfCompress.guide.faq2Q": "Will compressing make my PDF text blurry or unreadable?",
    "pdfCompress.guide.faq2A": "No! Vector text, system fonts, and document formatting remain crisp and fully searchable after compression.",
    "pdfCompress.guide.faq3Q": "Is there a file size or page limit?",
    "pdfCompress.guide.faq3A": "No artificial limits! You can compress large PDF documents for free as long as your device RAM can load them.",
    "pdfCompress.guide.faq4Q": "Why did some PDF files only shrink by a small percentage?",
    "pdfCompress.guide.faq4A": "PDFs that are already text-only or previously compressed have fewer redundant streams, resulting in smaller additional savings.",
    "pdfCompress.guide.faq5Q": "What is the difference between Recommended and High compression?",
    "pdfCompress.guide.faq5A": "Recommended optimizes binary object streams with zero visual difference. High compression optimizes more aggressively for maximum space reduction.",
    "pdfCompress.guide.faq6Q": "Can I compress password-protected PDF files?",
    "pdfCompress.guide.faq6A": "Please unlock the file first with our 'PDF Unlock' tool before compressing.",

