    "pdfProtect.guide.aboutTitle": "What is the PDF Password Protect Tool?",
    "pdfProtect.guide.aboutDesc": "This tool applies industry-standard PDF AES encryption directly inside your browser memory using WebCrypto and pdf-lib. Your password and confidential documents never touch any remote server, ensuring total privacy.",
    "pdfProtect.guide.howTitle": "How to Encrypt and Protect a PDF",
    "pdfProtect.guide.step1": "Drag & drop or select the PDF document you want to lock.",
    "pdfProtect.guide.step2": "Enter your desired open password and retype it in the confirmation box.",
    "pdfProtect.guide.step3": "Click 'Encrypt PDF & Download' to instantly receive your securely locked PDF file.",
    "pdfProtect.guide.featuresTitle": "Key Security Features & Highlights",
    "pdfProtect.guide.feat1Title": "100% Local Client-Side Security",
    "pdfProtect.guide.feat1Desc": "All cryptographic operations execute within your browser sandbox. Confidential contracts and trade secrets are never sent across the internet.",
    "pdfProtect.guide.feat2Title": "Industry-Standard PDF Encryption",
    "pdfProtect.guide.feat2Desc": "Applies standard AES encryption compliant with Adobe Acrobat, Chrome, Apple Preview, and global PDF viewers.",
    "pdfProtect.guide.feat3Title": "Real-time Password Strength Meter",
    "pdfProtect.guide.feat3Desc": "Instantly evaluates password complexity with visual indicators for length, numbers, and special symbols.",
    "pdfProtect.guide.feat4Title": "Lossless Layout & Vector Preservation",
    "pdfProtect.guide.feat4Desc": "Locks the document without altering font vectors, text sharpness, or image resolutions.",
    "pdfProtect.guide.useCasesTitle": "Popular Use Cases & Scenarios",
    "pdfProtect.guide.uc1Title": "Employment Contracts & Salary Slips",
    "pdfProtect.guide.uc1Desc": "Secure monthly salary statements, HR payroll, and signed employee contracts before sending via email.",
    "pdfProtect.guide.uc2Title": "Financial Statements & Tax Returns",
    "pdfProtect.guide.uc2Desc": "Protect corporate balance sheets, audit reports, and tax filings from unauthorized viewing.",
    "pdfProtect.guide.uc3Title": "Legal Agreements & NDAs",
    "pdfProtect.guide.uc3Desc": "Safeguard non-disclosure agreements, patent filings, and proprietary trade secrets shared with external partners.",
    "pdfProtect.guide.uc4Title": "Personal Identification & Medical Records",
    "pdfProtect.guide.uc4Desc": "Prevent unauthorized access to passport scans, medical test reports, and private family records.",
    "pdfProtect.guide.tipsTitle": "Security Best Practices & Tips",
    "pdfProtect.guide.tip1": "Use a combination of uppercase letters, numbers, and special characters (8+ characters) for optimal protection.",
    "pdfProtect.guide.tip2": "Share the document and password through separate communication channels (e.g., email document, SMS password).",
    "pdfProtect.guide.tip3": "Be sure to store the password in a password manager; standard encryption cannot be recovered if forgotten.",
    "pdfProtect.guide.faqTitle": "Frequently Asked Questions (FAQ)",
    "pdfProtect.guide.faq1Q": "Is my password or PDF file sent to any server?",
    "pdfProtect.guide.faq1A": "No! All encryption algorithms run 100% locally in your browser memory. No data or passwords ever leave your machine.",
    "pdfProtect.guide.faq2Q": "What PDF readers can open the encrypted document?",
