    "pdfProtect.guide.faq3Q": "Can I recover the PDF if I forget the password?",
    "pdfProtect.guide.faq3A": "No. Standard cryptographic security is unbreakable without the correct password. Please write down or store your password safely.",
    "pdfProtect.guide.faq4Q": "Is there a file size limit for encryption?",
    "pdfProtect.guide.faq4A": "No artificial limits. You can encrypt large PDF documents as long as your device RAM permits.",
    "pdfProtect.guide.faq5Q": "Does encrypting degrade document text or image quality?",
    "pdfProtect.guide.faq5A": "Not at all. The encryption layer secures the binary payload without modifying document layout, text sharpness, or image quality.",
    "pdfProtect.guide.faq6Q": "How do I remove the password later?",
    "pdfProtect.guide.faq6A": "You can use our 'PDF Unlock' tool anytime by entering the password to save a permanently unencrypted version.",

