    "imageResizer.guide.aboutDesc": "서버 업로드 없이 사용자의 웹 브라우저에서 PNG, JPG, WEBP 이미지의 가로/세로 해상도를 픽셀 및 퍼센트 단위로 자유롭게 조절하고 용량을 줄여주는 100% 로컬 유틸리티입니다.",
