    "imageResizer.guide.step2": "2. 원하는 가로/세로 픽셀을 입력하거나 50%, 75% 등 퍼센트 버튼을 누릅니다. 종횡비 고정 아이콘(🔗)이 켜져 있으면 비율이 왜곡되지 않습니다.",
