    "exifRemover.guide.aboutDesc": "EXIF(Exchangeable Image File Format)는 스마트폰이나 카메라인 사진 파일 내부에 숨겨진 상세 데이터입니다. 여기에는 정확한 GPS 위치 좌표, 카메라 시리얼 번호, 렌즈 스펙, 촬영 시각 등이 포함되어 있어 인터넷 공유 전 제거하는 것이 개인정보 보호에 필수적입니다.",
