    "exifRemover.guide.step2": "2. GPS 지도 위치, 카메라 모델, 촬영 날짜 등 상세 데이터를 실시간 조회합니다.",
    "exifRemover.guide.step3": "3. '모든 EXIF 메타데이터 완전 제거 후 다운로드' 버튼을 클릭하여 안전한 이미지를 저장합니다.",
