    "pdfSplit.selectAll": "전체 선택",
    "pdfSplit.deselectAll": "전체 해제",
    "pdfSplit.selectedPages": "개 페이지 선택됨",
    "pdfSplit.guide.title": "PDF 분할기 완벽 사용 가이드",
    "pdfSplit.guide.badge": "100% 무료 & 로컬 브라우저 처리",
    "pdfSplit.guide.aboutTitle": "PDF 분할기란 무엇인가요?",
    "pdfSplit.guide.aboutDesc": "PDF 분할기는 서버 업로드 없이 웹 브라우저 메모리(pdf-lib) 내에서 PDF 문서의 페이지를 자유롭게 분리, 추출, 쪼개어 새 PDF 파일로 만들어 주는 100% 안전한 무료 유틸리티입니다.",
    "pdfSplit.guide.howTitle": "PDF 페이지 분할 및 추출 방법",
    "pdfSplit.guide.step1": "분할하고 싶은 PDF 파일을 드래그하거나 클릭하여 업로드합니다.",
    "pdfSplit.guide.step2": "분할 방식을 선택합니다: '모든 페이지 분할', '페이지 범위 지정(예: 1-3, 5)', 또는 '썸네일 직접 선택'.",
    "pdfSplit.guide.step3": "'PDF 분할 실행하기' 버튼을 누르고 추출된 PDF 파일들을 즉시 다운로드합니다.",
    "pdfSplit.guide.featuresTitle": "PDF 분할기 핵심 강점 & 특징",
    "pdfSplit.guide.feat1Title": "100% 프라이빗 로컬 연산",
    "pdfSplit.guide.feat1Desc": "모든 페이지 분할이 사용자 PC/모바일 브라우저 메모리 내에서만 처리되어 계약서, 등본, 금융 서류 등 민감한 개인정보가 안전합니다.",
    "pdfSplit.guide.feat2Title": "실시간 썸네일 미리보기 & 선택",
    "pdfSplit.guide.feat2Desc": "전체 페이지를 시각적 썸네일로 보면서 원하는 페이지만 마우스 클릭으로 직관적으로 골라낼 수 있습니다.",
    "pdfSplit.guide.feat3Title": "3가지 맞춤형 분할 모드",
    "pdfSplit.guide.feat3Desc": "① 1장씩 전체 분할, ② 사용자 정의 범위 추출(예: 1-3, 5, 8-12), ③ 썸네일 직접 선택 모드를 완벽 지원합니다.",
    "pdfSplit.guide.feat4Title": "무손실(Lossless) 벡터 & OCR 보존",
    "pdfSplit.guide.feat4Desc": "단순 이미지 캡처가 아닌 원본 PDF 객체 트리를 복사하여 텍스트 검색, 폰트, 벡터 그래픽 및 하이퍼링크가 손상 없이 유지됩니다.",
    "pdfSplit.guide.useCasesTitle": "대표적인 실무 & 일상 활용 사례",
    "pdfSplit.guide.uc1Title": "필요한 페이지만 골라 제출",
    "pdfSplit.guide.uc1Desc": "수십 장의 계약서, 법원 서류, 등본에서 제출처에 필요한 페이지만 1~2장 깔끔하게 추출하여 전송.",
    "pdfSplit.guide.uc2Title": "논문 & 도서 특정 챕터 분리",
    "pdfSplit.guide.uc2Desc": "두꺼운 전공 서적이나 수백 페이지 학술 논문, E-Book에서 필요한 특정 챕터만 별도 파일로 분리 보관.",
    "pdfSplit.guide.uc3Title": "기밀/개인정보 페이지 제외",
    "pdfSplit.guide.uc3Desc": "회사 대외비 보고서나 제안서에서 내부 단가표, 개인정보 등 민감한 페이지를 제외하고 외부 공유용 PDF 제작.",
    "pdfSplit.guide.uc4Title": "대용량 스캔 문서 낱장 정리",
    "pdfSplit.guide.uc4Desc": "복합기에서 한 번에 묶음 스캔된 PDF를 1장씩 개별 파일로 분할하여 문서 관리 시스템에 자동 정리.",
    "pdfSplit.guide.tipsTitle": "PDF 분할 시 유용한 전문가 꿀팁",
    "pdfSplit.guide.tip1": "페이지 범위 지정 시 콤마(,)와 하이픈(-)을 조합하여 '1-5, 8, 12-15'와 같이 불연속적인 구간을 한 번에 추출할 수 있습니다.",
    "pdfSplit.guide.tip2": "썸네일 모드에서 '전체 선택'을 누른 후 제외하고 싶은 페이지만 체크 해제하면 작업 속도를 크게 단축할 수 있습니다.",
    "pdfSplit.guide.tip3": "분할 추출된 페이지들을 다른 문서와 합치고 싶을 땐 'PDF 합치기' 도구와 함께 사용해 보세요.",
    "pdfSplit.guide.faqTitle": "자주 묻는 질문 (FAQ)",
    "pdfSplit.guide.faq1Q": "중요 개인정보 PDF 파일을 분할해도 안전한가요?",
    "pdfSplit.guide.faq1A": "네, 100% 안전합니다! 모든 분할 처리가 사용자의 브라우저 내부(pdf-lib)에서 수행되며, 서버나 클라우드로 파일이 절대 전송되지 않습니다.",
    "pdfSplit.guide.faq2Q": "1페이지, 3페이지, 7-10페이지처럼 떨어진 페이지도 같이 추출할 수 있나요?",
    "pdfSplit.guide.faq2A": "네! 페이지 범위 입력창에 '1, 3, 7-10' 형식으로 입력하거나, 썸네일 미리보기 화면에서 원하는 페이지를 마우스로 직접 체크하시면 해당 페이지들만 묶어서 새 PDF로 추출됩니다.",
    "pdfSplit.guide.faq3Q": "추출된 PDF에서도 텍스트 드래그(복사)와 검색이 가능한가요?",
    "pdfSplit.guide.faq3A": "네! 원본 PDF의 텍스트와 폰트 구조를 그대로 복제하므로 텍스트 선택, 복사, 검색, 선명도가 원본과 동일하게 유지됩니다.",
    "pdfSplit.guide.faq4Q": "페이지 수나 파일 용량에 제한이 있나요?",
    "pdfSplit.guide.faq4A": "별도의 인위적인 제한이 없습니다! 기기 메모리가 허용하는 한 수백 페이지 분량의 대용량 PDF 문서도 무료로 분할할 수 있습니다.",
    "pdfSplit.guide.faq5Q": "'모든 페이지 1장씩 분할'을 선택하면 어떻게 다운로드되나요?",
    "pdfSplit.guide.faq5A": "각 페이지가 '[파일명]_page_1.pdf', '[파일명]_page_2.pdf' 등의 개별 파일로 즉시 생성되어 개별 또는 일괄 다운로드할 수 있습니다.",
    "pdfSplit.guide.faq6Q": "암호(비밀번호)가 걸려 있는 PDF도 분할할 수 있나요?",
    "pdfSplit.guide.faq6A": "비밀번호가 걸린 문서는 사전에 'PDF 잠금 해제' 도구에서 암호를 해제하신 후 업로드하시면 정상적으로 분할할 수 있습니다.",

