    "pdfCompress.guide.badge": "100% 무료 & 로컬 브라우저 처리",
    "pdfCompress.guide.aboutTitle": "PDF 압축 도구란 무엇인가요?",
    "pdfCompress.guide.aboutDesc": "서버 업로드 없이 브라우저 메모리(pdf-lib) 내에서 PDF 내부 개체 스트림과 중복 메타데이터를 재정렬 및 최적화하여 문서 용량을 획기적으로 줄여주는 100% 안전한 무료 유틸리티입니다.",
    "pdfCompress.guide.howTitle": "PDF 파일 용량 줄이는 방법",
    "pdfCompress.guide.step1": "용량을 줄이고 싶은 PDF 문서를 드래그하거나 클릭하여 업로드합니다.",
    "pdfCompress.guide.step2": "용도에 맞게 압축 레벨(추천 압축, 고압축, 저압축)을 선택합니다.",
    "pdfCompress.guide.step3": "'PDF 압축하기' 버튼을 누르고 용량이 절감된 최적화 PDF를 즉시 다운로드합니다.",
    "pdfCompress.guide.featuresTitle": "PDF 압축기 핵심 강점 & 특징",
    "pdfCompress.guide.feat1Title": "100% 프라이빗 로컬 연산",
    "pdfCompress.guide.feat1Desc": "문서 데이터가 외부 클라우드나 원격 서버로 전송되지 않고 사용자 기기 내부 메모리에서만 안전하게 최적화됩니다.",
    "pdfCompress.guide.feat2Title": "3단계 맞춤형 압축 레벨",
    "pdfCompress.guide.feat2Desc": "품질 균형(추천), 최대 다이어트(고압축), 원본 화질 보존(저압축) 중 상황에 맞게 1클릭으로 선택 가능합니다.",
    "pdfCompress.guide.feat3Title": "실시간 용량 절감률 측정",
    "pdfCompress.guide.feat3Desc": "원본 크기 대비 최종 압축 크기 및 줄어든 용량(%)을 실시간 계측기로 한눈에 확인 후 저장할 수 있습니다.",
    "pdfCompress.guide.feat4Title": "텍스트 & 벡터 폰트 선명도 보존",
    "pdfCompress.guide.feat4Desc": "단순 화질 뭉개기가 아닌 불필요한 바이너리 스트림 정리를 통해 글자 폰트와 인쇄 선명도를 깨끗하게 유지합니다.",
    "pdfCompress.guide.useCasesTitle": "대표적인 실무 & 일상 활용 사례",
    "pdfCompress.guide.uc1Title": "이메일 첨부 용량 초과 해결",
    "pdfCompress.guide.uc1Desc": "네이버, 다음, Gmail, 사내 메일의 10MB/25MB 대용량 첨부 파일 제한에 걸리지 않도록 가볍게 축소.",
    "pdfCompress.guide.uc2Title": "공공기관 · 채용 사이트 서류 제출",
    "pdfCompress.guide.uc2Desc": "정부 민원 포털, 대기업/공채 이력서 접수 시스템의 2MB~5MB 업로드 제한 규격에 맞춰 손쉽게 제출.",
    "pdfCompress.guide.uc3Title": "모바일 & 클라우드 저장 용량 절약",
    "pdfCompress.guide.uc3Desc": "구글 드라이브, 드롭박스, 스마트폰 내 보관 중인 PDF 서류 아카이브를 경량화하여 소중한 저장 공간 확보.",
    "pdfCompress.guide.uc4Title": "대용량 E-Book 및 발표자료 경량화",
    "pdfCompress.guide.uc4Desc": "수십 장의 고화질 프레젠테이션 슬라이드나 E-Book 문서를 가볍게 만들어 모바일에서도 버벅임 없이 열람.",
    "pdfCompress.guide.tipsTitle": "PDF 압축 시 유용한 전문가 꿀팁",
    "pdfCompress.guide.tip1": "일반적인 업무 보고서나 공문서는 기본 설정된 '추천 압축'을 사용하면 가독성 손실 없이 최적의 용량을 얻을 수 있습니다.",
    "pdfCompress.guide.tip2": "스캔 이미지나 고화질 사진이 다수 포함된 PDF는 '고압축'을 적용할 때 가장 큰 용량 감소 효과를 체감할 수 있습니다.",
    "pdfCompress.guide.tip3": "여러 문서를 합쳐서 한 번에 제출할 때는 'PDF 합치기' 도구로 먼저 합친 후 최종적으로 압축하면 편리합니다.",
    "pdfCompress.guide.faqTitle": "자주 묻는 질문 (FAQ)",
    "pdfCompress.guide.faq1Q": "업로드한 PDF 문서가 서버로 전송되나요?",
    "pdfCompress.guide.faq1A": "아닙니다. 모든 계산 및 압축 최적화 과정은 100% 사용자의 브라우저 로컬 환경(pdf-lib)에서만 수행되며 파일이 외부로 유출되지 않습니다.",
    "pdfCompress.guide.faq2Q": "압축하면 PDF 문서의 텍스트가 깨지거나 흐려지나요?",
    "pdfCompress.guide.faq2A": "아닙니다! 추천 레벨을 사용하면 텍스트 벡터 폰트와 문서 구조를 온전히 보존하므로 글자가 흐려지지 않고 텍스트 검색(OCR)도 그대로 유지됩니다.",
    "pdfCompress.guide.faq3Q": "파일 용량이나 페이지 수에 제한이 있나요?",
    "pdfCompress.guide.faq3A": "인위적인 제한이 없습니다! 사용자의 컴퓨터 및 스마트폰 메모리가 허용하는 한 수백 페이지의 대용량 파일도 무료로 빠르게 처리됩니다.",
    "pdfCompress.guide.faq4Q": "압축 후에도 용량이 거의 줄어들지 않는 파일은 왜 그런가요?",
    "pdfCompress.guide.faq4A": "이미 타 프로그램에서 최적화되었거나, 텍스트 위주로 구성되어 이미 용량이 극도로 작은 PDF는 추가로 줄일 수 있는 바이너리 여백이 적기 때문입니다.",
    "pdfCompress.guide.faq5Q": "추천 압축과 고압축의 차이는 무엇인가요?",
    "pdfCompress.guide.faq5A": "추천 압축은 시각적 품질 변화가 전혀 없는 무손실 스트림 압축이며, 고압축은 파일 용량을 극단적으로 줄이기 위해 내부 리소스를 더 강력하게 재압축합니다.",
    "pdfCompress.guide.faq6Q": "암호(비밀번호)가 걸려 있는 PDF도 압축할 수 있나요?",
    "pdfCompress.guide.faq6A": "비밀번호가 걸린 문서는 'PDF 잠금 해제' 도구에서 먼저 암호를 해제하신 후 업로드하시면 정상적으로 압축할 수 있습니다.",

