    "imageToPdf.guide.badge": "100% 무료 & 클라이언트 변환",
    "imageToPdf.guide.aboutTitle": "이미지 PDF 변환기란 무엇인가요?",
    "imageToPdf.guide.aboutDesc": "JPG, PNG, WebP, GIF, BMP 등 여러 형식의 사진이나 스캔본을 서버 전송 없이 브라우저 내에서 순서대로 정렬하여 하나의 규격화된 고화질 PDF 문서로 패키징해 주는 무료 도구입니다.",
    "imageToPdf.guide.howTitle": "이미지를 PDF로 변환하는 방법",
    "imageToPdf.guide.step1": "PDF로 묶고 싶은 사진, 영수증, 스캔 문서를 한 번에 드래그하거나 선택하여 업로드합니다.",
    "imageToPdf.guide.step2": "화살표 버튼(▲/▼)으로 페이지 순서를 정렬하고, 용지 규격(A4, Letter, 원본 맞춤)과 여백을 설정합니다.",
    "imageToPdf.guide.step3": "'PDF로 일괄 변환하기'를 클릭하고 1초 만에 완성된 PDF를 즉시 다운로드합니다.",
    "imageToPdf.guide.featuresTitle": "이미지 PDF 변환기 핵심 강점 & 특징",
    "imageToPdf.guide.feat1Title": "다중 이미지 일괄 병합",
    "imageToPdf.guide.feat1Desc": "수십~수백 장의 사진을 한 번에 업로드하여 페이지 순서대로 결합된 단일 PDF로 초고속 변환합니다.",
    "imageToPdf.guide.feat2Title": "규격 용지 & 원본 맞춤 레이아웃",
    "imageToPdf.guide.feat2Desc": "공문서용 A4/Letter 규격(여백 조절 가능)부터 사진 원본 크기를 그대로 유지하는 'Fit' 모드까지 자유롭게 지원합니다.",
    "imageToPdf.guide.feat3Title": "원클릭 페이지 순서 재배열",
    "imageToPdf.guide.feat3Desc": "각 이미지 카드에 있는 상하 이동 화살표를 눌러 표지, 본문, 증빙 서류의 순서를 손쉽게 바꿀 수 있습니다.",
    "imageToPdf.guide.feat4Title": "100% 프라이빗 로컬 렌더링",
    "imageToPdf.guide.feat4Desc": "개인 사진, 신분증, 결제 영수증이 외부 서버로 전송되지 않고 브라우저 Canvas/pdf-lib에서 안전하게 처리됩니다.",
    "imageToPdf.guide.useCasesTitle": "대표적인 실무 & 일상 활용 사례",
    "imageToPdf.guide.uc1Title": "영수증 및 지출결의서 정산",
    "imageToPdf.guide.uc1Desc": "스마트폰으로 촬영한 여러 장의 영수증과 세금계산서 사진을 1개의 깔끔한 정산용 PDF로 묶어 제출.",
    "imageToPdf.guide.uc2Title": "신분증 · 증명서류 일괄 제출",
    "imageToPdf.guide.uc2Desc": "주민등록증, 통장 사본, 자격증 사진을 A4 표준 규격의 정갈한 전자문서로 변환하여 기관에 전송.",
    "imageToPdf.guide.uc3Title": "포트폴리오 & 룩북 카탈로그 제작",
    "imageToPdf.guide.uc3Desc": "디자인 시안, 일러스트, 촬영 포트폴리오를 고화질 PDF 브로슈어로 묶어 고객사나 면접관에게 공유.",
    "imageToPdf.guide.uc4Title": "스마트폰 촬영 서류 전자문서화",
    "imageToPdf.guide.uc4Desc": "책 전공서적 낱장, 강의 필기, 계약서 사진을 A4 규격에 맞춰 책 형태의 전자 PDF 파일로 아카이빙.",
    "imageToPdf.guide.tipsTitle": "이미지 변환 시 유용한 전문가 꿀팁",
    "imageToPdf.guide.tip1": "공식 기관이나 회사에 제출할 때는 'A4 표준' + '보통 여백'을 선택하면 인쇄 및 열람 시 가장 깔끔합니다.",
    "imageToPdf.guide.tip2": "여백 없이 사진 원본 그대로 꽉 찬 앨범을 만들고 싶다면 '용지 크기: 이미지 맞춤(Fit)' + '여백 없음'을 선택하세요.",
    "imageToPdf.guide.tip3": "변환 전 위(▲)/아래(▼) 버튼으로 파일 목록의 순서를 확인하면 원하는 페이지 순서대로 정확히 완성됩니다.",
    "imageToPdf.guide.faqTitle": "자주 묻는 질문 (FAQ)",
    "imageToPdf.guide.faq1Q": "제 사진이나 개인 서류가 서버에 저장되나요?",
    "imageToPdf.guide.faq1A": "전혀 저장되지 않습니다! 모든 이미지 변환 및 PDF 조합은 사용자 기기의 브라우저 메모리 내부에서만 100% 로컬 연산됩니다.",
    "imageToPdf.guide.faq2Q": "JPG, PNG 외에 WebP나 GIF, BMP 파일도 변환 가능한가요?",
    "imageToPdf.guide.faq2A": "네! JPG, PNG는 물론 최신 WebP, GIF, BMP 등 브라우저가 지원하는 모든 그래픽 형식을 자동으로 변환합니다.",
    "imageToPdf.guide.faq3Q": "한 번에 몇 장의 사진까지 변환할 수 있나요?",
    "imageToPdf.guide.faq3A": "인위적인 제한이 없습니다. 기기 RAM이 허용하는 한 수십 장~수백 장의 이미지를 자유롭게 묶어 변환할 수 있습니다.",
    "imageToPdf.guide.faq4Q": "A4 용지로 변환 시 사진 비율이 찌그러지거나 잘리나요?",
    "imageToPdf.guide.faq4A": "아닙니다! 원본 이미지의 가로세로 비율(Aspect Ratio)을 100% 유지하며 지정된 여백 내에 완벽한 비율로 자동 배치됩니다.",
    "imageToPdf.guide.faq5Q": "생성되는 PDF 파일 용량을 줄이고 싶으면 어떻게 하나요?",
    "imageToPdf.guide.faq5A": "설정 패널에서 '이미지 화질 / 압축' 옵션을 '용량 압축' 또는 '표준 최적화'로 선택하시면 가벼운 용량의 PDF가 생성됩니다.",
    "imageToPdf.guide.faq6Q": "스마트폰(아이폰/안드로이드)에서도 사용할 수 있나요?",
    "imageToPdf.guide.faq6A": "네! 모바일 웹 환경에 완벽 대응하여 Safari, Chrome 등 모바일 브라우저에서도 즉시 변환하고 저장할 수 있습니다.",

