    "pdfProtect.guide.feat1Desc": "모든 암호화 연산이 내 기기 브라우저 메모리 안에서만 수행되므로 기밀 계약서나 개인정보가 외부로 유출될 위험이 전혀 없습니다.",
    "pdfProtect.guide.feat2Title": "국제 표준 PDF 암호화 규격",
    "pdfProtect.guide.feat2Desc": "Adobe Acrobat, 크롬, 사파리, 스마트폰 뷰어 등 전 세계 모든 표준 PDF 리더와 100% 호환되는 표준 암호화가 적용됩니다.",
    "pdfProtect.guide.feat3Title": "실시간 비밀번호 강도 측정",
    "pdfProtect.guide.feat3Desc": "글자 수, 대소문자, 숫자, 특수문자 조합을 실시간 분석하여 안전한 비밀번호 설정을 직관적으로 돕습니다.",
    "pdfProtect.guide.feat4Title": "문서 레이아웃 및 화질 무손실 보존",
    "pdfProtect.guide.feat4Desc": "암호화 보안 계층만 추가할 뿐 원본 텍스트 벡터와 고화질 이미지를 100% 원본 그대로 유지합니다.",
    "pdfProtect.guide.useCasesTitle": "대표적인 실무 & 일상 활용 사례",
    "pdfProtect.guide.uc1Title": "근로계약서 & 급여명세서 보안 발송",
    "pdfProtect.guide.uc1Desc": "임직원 월급 명세서, 연봉 계약서, 인사 서류에 비밀번호를 설정하여 이메일 전송 시 유출 방지.",
    "pdfProtect.guide.uc2Title": "기업 재무제표 & 세무 서류 보호",
    "pdfProtect.guide.uc2Desc": "외부 감사 보고서, 결산서, 부가세 증빙 서류를 암호화하여 인가된 수신자만 열람할 수 있도록 잠금.",
    "pdfProtect.guide.uc3Title": "비밀유지계약서(NDA) & 특허 문서 잠금",
    "pdfProtect.guide.uc3Desc": "기업 간 NDA 계약서, 신규 사업 기획안, 지식재산권 문서를 외부 파트너와 안전하게 공유.",
    "pdfProtect.guide.uc4Title": "신분증 사본 & 의료 진단서 보호",
    "pdfProtect.guide.uc4Desc": "여권/주민등록증 스캔본, 병원 진단서, 가족관계증명서 등 개인정보 문서를 안전하게 보호.",
    "pdfProtect.guide.tipsTitle": "비밀번호 설정 시 유용한 보안 팁",
    "pdfProtect.guide.tip1": "영문 대소문자, 숫자, 특수문자를 혼합하여 8자 이상의 강력한 비밀번호를 설정하는 것을 권장합니다.",
    "pdfProtect.guide.tip2": "수신자에게 문서를 보낼 때는 문서 전달 채널(이메일)과 비밀번호 전달 채널(문자/메신저)을 분리하세요.",
    "pdfProtect.guide.tip3": "표준 암호화 특성상 비밀번호를 잊어버리면 복구가 불가능하므로 꼭 안전한 곳에 기록해 두세요.",
    "pdfProtect.guide.faqTitle": "자주 묻는 질문 (FAQ)",
    "pdfProtect.guide.faq1Q": "비밀번호를 설정할 때 파일이나 암호가 서버로 전송되나요?",
    "pdfProtect.guide.faq1A": "전혀 전송되지 않습니다! desktools.run의 모든 암호화 처리는 브라우저 내부 WebCrypto 엔진에서 100% 로컬로 수행되므로 비밀번호나 문서 내용이 유출될 염려가 없습니다.",
    "pdfProtect.guide.faq2Q": "암호화된 PDF는 어떤 뷰어 프로그램에서 열 수 있나요?",
    "pdfProtect.guide.faq2A": "Adobe Acrobat Reader, 크롬/엣지/사파리 브라우저, 스마트폰 기본 PDF 뷰어 등 전 세계 모든 표준 PDF 리더에서 비밀번호를 입력하여 정상적으로 열 수 있습니다.",
    "pdfProtect.guide.faq3Q": "비밀번호를 분실하면 복구할 수 있나요?",
    "pdfProtect.guide.faq3A": "표준 보안 규격에 따라 암호화되므로 비밀번호를 분실하면 작성자 본인도 복구할 수 없습니다. 설정하신 비밀번호를 꼭 안전한 곳에 메모해 두세요.",
    "pdfProtect.guide.faq4Q": "암호화할 수 있는 PDF 파일 크기 제한이 있나요?",
    "pdfProtect.guide.faq4A": "인위적인 용량 제한이 없습니다. 기기의 메모리가 허용하는 한 수백 페이지의 대용량 PDF도 안전하게 암호화할 수 있습니다.",
    "pdfProtect.guide.faq5Q": "암호화 시 문서 화질이나 텍스트 선명도가 저하되나요?",
    "pdfProtect.guide.faq5A": "아닙니다! 암호화 보안 레이어만 추가할 뿐 원본 문서의 텍스트, 벡터 그래픽, 이미지 해상도는 100% 원본 그대로 유지됩니다.",
    "pdfProtect.guide.faq6Q": "나중에 비밀번호를 영구 해제하고 싶으면 어떻게 하나요?",
    "pdfProtect.guide.faq6A": "저희 사이트의 'PDF 비밀번호 해제' 도구에서 비밀번호를 한 번 입력하시면 암호 없는 일반 PDF로 언제든 다시 저장할 수 있습니다.",

