    "csvToJson.guide.aboutTitle": "CSV ➔ JSON 변환기란 무엇인가요?",
    "csvToJson.guide.aboutDesc": "CSV 형식의 스프레드시트 데이터를 JavaScript 및 API에서 바로 사용할 수 있는 JSON 형식으로 변환하는 도구입니다. 모든 처리는 사용자의 브라우저 내에서만 수행되어 정보가 안전합니다.",
