    "csvToJson.guide.step3": "3. 실시간으로 변환된 JSON 및 테이블을 확인하고 '복사' 또는 '.json 저장' 버튼을 누릅니다.",
    "csvToJson.guide.faqTitle": "자주 묻는 질문",
    "csvToJson.guide.faq1Q": "파일이 서버로 업로드되나요?",
    "csvToJson.guide.faq1A": "아니요. 모든 CSV 파싱 및 JSON 변환은 사용자의 브라우저 메모리 내에서만 100% 로컬 처리됩니다.",
    "csvToJson.guide.faq2Q": "어떤 구분자를 지원하나요?",
    "csvToJson.guide.faq2A": "쉼표(,), 세미콜론(;), 탭(\\t), 파이프(|)를 지원합니다.",
    "csvToJson.guide.faq3Q": "한글이나 특수문자도 처리되나요?",
    "csvToJson.guide.faq3A": "네. UTF-8 인코딩 기반으로 한국어를 포함한 모든 언어와 특수문자가 정확하게 처리됩니다.",
    "csvToJson.guide.faq4Q": "출력 형식 '객체 { }'는 무엇인가요?",
    "csvToJson.guide.faq4A": "배열 대신 첫 번째 컬럼 값을 키로 사용하는 객체 형태로 출력하는 옵션입니다.",
    "pages.about.title": "desktools.run 소개",
    "pages.about.subtitle": "100% 브라우저 내 로컬 처리(Zero Server Upload)로 개인정보를 철저히 보호하는 웹 유틸리티 서비스입니다.",
    "pages.about.badge": "개인정보 보호 최우선 & 초고속 성능",
    "pages.about.card1.title": "100% 브라우저 로컬 데이터 보안",
    "pages.about.card1.desc": "업로드한 파일과 데이터는 외부 서버로 전송되지 않습니다. 모든 작업은 100% 사용자의 브라우저 메모리 안에서 처리됩니다.",
    "pages.about.card2.title": "업로드 지연 없는 즉각적 성능",
    "pages.about.card2.desc": "서버 업로드 대기 시간이 없습니다. WebAssembly와 HTML5 Canvas API를 통해 무지연 빠른 결과를 제공합니다.",
    "pages.about.card3.title": "회원가입 & 결제 불필요",
    "pages.about.card3.desc": "회원가입, 구독료, 광고, 숨겨진 비용이 일체 없습니다. 웹사이트를 열고 바로 사용하세요.",
    "pages.about.why.title": "desktools.run을 만든 이유",
    "pages.about.why.p1": "기존의 웹 변환 서비스들은 소중한 PDF, 개인 이미지, 기밀 문서를 원격 클라우드 서버로 업로드하도록 요구합니다. 하지만 desktools.run은 사용자의 개인정보와 파일이 오직 사용자의 기기 안에만 머물러야 한다고 믿습니다.",
    "pages.about.why.p2": "최신 WebAssembly, HTML5 Canvas, Web Crypto API 등의 웹 기술을 활용하여, 개인정보 노출 위험 없이 데스크톱 앱 수준의 빠른 성능을 웹 브라우저 안으로 가져왔습니다.",
    "pages.blog.title": "개발 블로그 & 가이드",
    "pages.blog.subtitle": "웹 스토리지, WebAssembly, 웹 이미지 최적화 및 유용한 기술 팁 아티클입니다.",
    "pages.request.title": "새로운 도구 제안하기",
    "pages.request.subtitle": "필요하신 새로운 도구나 기능 개선 아이디어가 있으시면 언제든지 개발팀에 제안해 주세요.",
    "pages.status.title": "서비스 및 엔진 운영 상태",
    "pages.status.subtitle": "클라이언트 분안 엔진, WebAssembly 모듈, CDN 정적 전달의 실시간 운영 상태를 확인합니다.",
    "pages.changelog.title": "서비스 변경 이력 & 타임라인",
    "pages.changelog.subtitle": "desktools.run의 신규 도구 출시, 성능 개선 및 버전 업데이트 히스토리입니다.",
