    "pdfMerger.guide.uc3Desc": "週ごとの講義スライドや学術論文、電子書籍の章別PDFを1冊のファイルとしてまとめる。",
    "pdfMerger.guide.uc4Title": "請求書・領収書の経費証憑まとめ",
    "pdfMerger.guide.uc4Desc": "月別・プロジェクト別に発行された電子請求書や領収書PDFを日付順に整理して会計提出用ファイルを作成。",
    "pdfMerger.guide.tipsTitle": "知っておくと便利なプロの活用ヒント",
    "pdfMerger.guide.tip1": "パスワード保護されたPDFは、事前に「PDFロック解除」ツールで解除してからアップロードするとスムーズに結合できます。",
    "pdfMerger.guide.tip2": "A4、Letter、A3など異なる用紙サイズや縦横の向きが混在していても、それぞれのページ設定を保持したまま結合されます。",
    "pdfMerger.guide.tip3": "表紙、目次、本文の順序が正しいか、ファイルカード右側の上下矢印で確認してから結合してください。",
    "pdfMerger.guide.faqTitle": "よくある質問 (FAQ)",
    "pdfMerger.guide.faq1Q": "PDFファイルは外部サーバーに送信・保存されますか？",
    "pdfMerger.guide.faq1A": "いいえ。desktools.runのすべてのPDF処理はWebAssemblyおよびpdf-libエンジンにより、ブラウザメモリ内で100%ローカルに実行され、タブを閉じると即座に破棄されます。",
    "pdfMerger.guide.faq2Q": "結合後のPDFでもテキスト検索やコピーは可能ですか？",
    "pdfMerger.guide.faq2A": "はい！PDFの内部オブジェクト構造をそのまま保持して結合するため、テキスト選択、検索、埋め込みフォント、リンクは完全に維持されます。",
    "pdfMerger.guide.faq3Q": "結合できるPDFのファイル数やページ数に制限はありますか？",
    "pdfMerger.guide.faq3A": "人工的な制限は一切ありません。お使いのPCやスマホのブラウザRAMメモリが許す限り、数十個のファイルも一括結合できます。",
    "pdfMerger.guide.faq4Q": "異なるサイズ(A4, Letter)や縦横が混ざっていても結合できますか？",
    "pdfMerger.guide.faq4A": "はい、可能です。各ページの固有の解像度や回転角度（縦・横）を損なうことなく1つのドキュメントに結合します。",
    "pdfMerger.guide.faq5Q": "結合前にファイルの順序を変更するにはどうすればよいですか？",
    "pdfMerger.guide.faq5A": "ファイル追加後、リストの各カードにある上(▲)・下(▼)ボタンを押すことで、自由に出力順序を並べ替えられます。",
    "pdfMerger.guide.faq6Q": "スマートフォンやタブレットでも使用できますか？",
    "pdfMerger.guide.faq6A": "はい！Chrome、Safari、Samsung Internetなど主要なモバイルブラウザに対応しており、スマホでも快適にご利用いただけます。",
