    "pdfSplit.selectedPages": "ページ選択済み",
    "pdfSplit.guide.title": "PDF分割・ページ抽出完全ガイド",
    "pdfSplit.guide.badge": "100% 完全無料 & ブラウザ内処理",
    "pdfSplit.guide.aboutTitle": "PDF分割・抽出ツールとは？",
    "pdfSplit.guide.aboutDesc": "外部サーバーへファイルを送信せず、ブラウザのメモリ内(pdf-lib)だけでPDFのページを個別に抽出したり、指定した範囲で安全に分割できる100%無料のローカルユーティリティです。",
    "pdfSplit.guide.howTitle": "PDFページの分割・抽出方法",
    "pdfSplit.guide.step1": "分割したいPDFファイルをドラッグ＆ドロップまたはクリックしてアップロードします。",
    "pdfSplit.guide.step2": "分割モードを選択します（全ページ分割、範囲指定 例: 1-3, 5、またはサムネイル直接選択）。",
    "pdfSplit.guide.step3": "「PDF分割を実行する」ボタンをクリックし、抽出されたファイルを即座にダウンロードします。",
    "pdfSplit.guide.featuresTitle": "PDF分割ツールの主な特徴と強み",
    "pdfSplit.guide.feat1Title": "100% クライアントサイドの安全性",
    "pdfSplit.guide.feat1Desc": "すべての分割処理はお使いの端末のブラウザ内で完結。機密契約書や個人情報が外部サーバーに送信される心配はありません。",
    "pdfSplit.guide.feat2Title": "リアルタイムサムネイルプレビュー",
    "pdfSplit.guide.feat2Desc": "全ページを視覚的なサムネイルで確認しながら、必要なページだけをワンクリックで直感的に選択・抽出できます。",
    "pdfSplit.guide.feat3Title": "3つの柔軟な分割モード",
    "pdfSplit.guide.feat3Desc": "① 1ページずつの全分割、② 複雑な範囲指定（例：1-3, 5, 8-12）、③ サムネイル直接クリック抽出に完全対応。",
    "pdfSplit.guide.feat4Title": "テキスト・ベクターの完全無損失保持",
    "pdfSplit.guide.feat4Desc": "ネイティブなPDFオブジェクト構造をそのまま複製して抽出するため、テキスト検索(OCR)やフォントの鮮明さが維持されます。",
    "pdfSplit.guide.useCasesTitle": "ビジネス・日常での代表的な活用例",
    "pdfSplit.guide.uc1Title": "必要なページだけを抽出して提出",
    "pdfSplit.guide.uc1Desc": "数十ページの契約書や公的証明書から、提出先で要求された1〜2ページだけを綺麗に切り出して送信。",
    "pdfSplit.guide.uc2Title": "論文・電子書籍の特定章の切り離し",
    "pdfSplit.guide.uc2Desc": "大容量の学術論文や専門書E-Bookから、必要な章（チャプター）だけを個別ファイルとして保存・整理。",
    "pdfSplit.guide.uc3Title": "機密・個人情報ページの除外",
    "pdfSplit.guide.uc3Desc": "社外共有用の提案書や報告書から、社内価格表や個人情報が含まれるページを除外して新PDFを作成。",
    "pdfSplit.guide.uc4Title": "一括スキャンPDFの個別バラシ",
    "pdfSplit.guide.uc4Desc": "複合機でまとめてスキャンした大量の書類束を1ページごとの個別PDFに自動分割して文書管理システムへ登録。",
    "pdfSplit.guide.tipsTitle": "知っておくと便利なプロの活用ヒント",
    "pdfSplit.guide.tip1": "範囲指定欄ではカンマ(,)とハイフン(-)を組み合わせて「1-5, 8, 12-15」のように不連続な複数範囲を一度に抽出できます。",
    "pdfSplit.guide.tip2": "サムネイル選択モードで「すべて選択」を押した後、不要なページだけチェックを外すと作業がスムーズです。",
    "pdfSplit.guide.tip3": "分割抽出したページを他の書類とまとめたい場合は、「PDF結合」ツールと組み合わせてご活用ください。",
    "pdfSplit.guide.faqTitle": "よくある質問 (FAQ)",
    "pdfSplit.guide.faq1Q": "機密性の高いPDFファイルを分割しても安全ですか？",
    "pdfSplit.guide.faq1A": "はい、完全に安全です！すべてのページ抽出および分割処理はローカルのブラウザメモリ（pdf-lib）で完結し、サーバーにファイルが送信されることはありません。",
    "pdfSplit.guide.faq2Q": "離れた位置にある複数のページ（例：1, 3, 5）を指定して抽出できますか？",
    "pdfSplit.guide.faq2A": "はい、可能です。範囲指定入力欄に「1, 3, 5」とカンマ区切りで入力するか、サムネイル選択画面で直接チェックマークを入れて抽出し、1つのPDFにまとめることができます。",
    "pdfSplit.guide.faq3Q": "抽出されたPDFでもテキスト検索や文字コピーは可能ですか？",
    "pdfSplit.guide.faq3A": "はい！画像キャプチャではなくネイティブPDFページオブジェクトを抽出するため、テキスト選択、コピー、検索機能がすべてそのまま維持されます。",
    "pdfSplit.guide.faq4Q": "ページ数やファイルサイズに制限はありますか？",
    "pdfSplit.guide.faq4A": "いいえ、制限はありません。お使いの端末メモリの許す限り、何百ページもある巨大なPDFファイルでも無料で安全に分割処理が可能です。",
    "pdfSplit.guide.faq5Q": "「全ページ分割」を選ぶとファイルはどのようにダウンロードされますか？",
    "pdfSplit.guide.faq5A": "各ページが「[ファイル名]_page_1.pdf」、「[ファイル名]_page_2.pdf」などの単一ページファイルとして個別に生成され、ダウンロードできます。",
    "pdfSplit.guide.faq6Q": "パスワードで保護されたPDFも分割できますか？",
    "pdfSplit.guide.faq6A": "パスワードがかかっているファイルは、事前に「PDFロック解除」ツールで解除してからアップロードすると正常に分割できます。",

