    "pdfCompress.title": "PDF圧縮",
    "pdfCompress.subtitle": "目に見える画質低下なしにPDFのファイルサイズを軽量化・圧縮します。",
    "pdfCompress.dropPrompt": "PDFファイルをここにドラッグ＆ドロップするか、クリックして選択...",
