    "pdfCompress.reset": "別のPDFを圧縮する",
    "pdfCompress.guide.title": "PDF容量削減・圧縮完全ガイド",
    "pdfCompress.guide.badge": "100% 完全無料 & ブラウザ内処理",
    "pdfCompress.guide.aboutTitle": "PDF圧縮ツールとは？",
    "pdfCompress.guide.aboutDesc": "外部サーバーにファイルを送信せず、ブラウザのメモリ内(pdf-lib)だけでPDF内部の不要なメタデータやオブジェクトストリームを最適化し、安全かつ高速にファイル容量を軽量化する100%無料のローカルツールです。",
    "pdfCompress.guide.howTitle": "PDFのファイルサイズを軽量化する方法",
    "pdfCompress.guide.step1": "容量を小さくしたいPDFファイルをドラッグ＆ドロップまたはクリックしてアップロードします。",
    "pdfCompress.guide.step2": "用途に合わせて圧縮レベル（推奨圧縮、高圧縮、低圧縮）を選択します。",
    "pdfCompress.guide.step3": "「PDFを圧縮する」をクリックし、軽量化されたPDFを即座にダウンロードします。",
    "pdfCompress.guide.featuresTitle": "PDF圧縮ツールの主な特徴と強み",
    "pdfCompress.guide.feat1Title": "100% クライアントサイドのプライバシー保護",
    "pdfCompress.guide.feat1Desc": "書類データが外部サーバーへ送信されることは一切なく、お使いのPCやスマホのブラウザメモリ内だけで安全に処理されます。",
    "pdfCompress.guide.feat2Title": "3段階の選べる圧縮プリセット",
    "pdfCompress.guide.feat2Desc": "品質バランス重視（推奨）、容量大幅削減（高圧縮）、最高画質維持（低圧縮）からワンクリックで選択可能。",
    "pdfCompress.guide.feat3Title": "リアルタイム削減率メーター",
    "pdfCompress.guide.feat3Desc": "圧縮前の元の容量、圧縮後の仕上がり容量、削減率（%）をダウンロード前にひと目で確認できます。",
    "pdfCompress.guide.feat4Title": "テキスト・文字フォントの鮮明さを維持",
    "pdfCompress.guide.feat4Desc": "文字を無理に画像化してぼかすのではなく、内部ストリーム構造を最適化するためテキスト検索(OCR)も鮮明に保持されます。",
    "pdfCompress.guide.useCasesTitle": "ビジネス・日常での代表的な活用例",
    "pdfCompress.guide.uc1Title": "メール添付容量オーバーの解決",
    "pdfCompress.guide.uc1Desc": "Gmail、Outlook、企業メールの10MB/25MB容量制限を回避し、スムーズに送信できるよう軽量化。",
    "pdfCompress.guide.uc2Title": "公的機関・採用ポータルへの提出",
    "pdfCompress.guide.uc2Desc": "就職活動のエントリーシートや自治体申請サイトの厳しいアップロード容量制限（2MB〜5MB等）に合わせてサイズ調整。",
    "pdfCompress.guide.uc3Title": "スマホ＆クラウドストレージの節約",
    "pdfCompress.guide.uc3Desc": "Googleドライブ、Dropbox、端末ストレージに保管している大量のPDF文書をスリム化して空き容量を確保。",
    "pdfCompress.guide.uc4Title": "大容量電子書籍・プレゼン資料の最適化",
    "pdfCompress.guide.uc4Desc": "画像が多く重い企画書やE-Bookを軽くして、スマホやタブレットでも軽快に閲覧できるように最適化。",
    "pdfCompress.guide.tipsTitle": "知っておくと便利なプロの活用ヒント",
    "pdfCompress.guide.tip1": "通常のビジネス文書や報告書には、画質劣化が一切ない標準の「推奨圧縮」が最も適しています。",
    "pdfCompress.guide.tip2": "スキャン画像や高解像度写真が大量に含まれるPDFは、「高圧縮」を選択すると劇的な削減効果が得られます。",
    "pdfCompress.guide.tip3": "複数のファイルをまとめて送る場合は、先に「PDF結合」で1つにまとめてから圧縮すると効率的です。",
    "pdfCompress.guide.faqTitle": "よくある質問 (FAQ)",
    "pdfCompress.guide.faq1Q": "アップロードしたPDFファイルはサーバーに送信されますか？",
    "pdfCompress.guide.faq1A": "いいえ、送信されません！すべての最適化処理はお使いのブラウザ内（pdf-lib）で完結するため、機密情報が外部に漏れる心配はありません。",
    "pdfCompress.guide.faq2Q": "圧縮すると文字がぼやけたり読みにくくなりますか？",
    "pdfCompress.guide.faq2A": "いいえ！ベクターフォントやテキストレイアウトはそのまま維持されるため、文字の鮮明さや検索機能は劣化しません。",
    "pdfCompress.guide.faq3Q": "ファイルサイズやページ数に制限はありますか？",
    "pdfCompress.guide.faq3A": "人工的な制限はありません。お使いの端末メモリが許す限り、何百ページもある大容量ファイルでも無料で圧縮できます。",
    "pdfCompress.guide.faq4Q": "圧縮してもあまりサイズが小さくならないのはなぜですか？",
    "pdfCompress.guide.faq4A": "すでに他のソフトで最適化済みの場合や、テキスト中心で元から容量が極めて小さいPDFは削減余地が少ないためです。",
    "pdfCompress.guide.faq5Q": "「推奨圧縮」と「高圧縮」の違いは何ですか？",
    "pdfCompress.guide.faq5A": "推奨圧縮は見た目の画質を変えずに不要データを整理する無損失圧縮です。高圧縮は容量削減を最優先に強力な再圧縮を行います。",
    "pdfCompress.guide.faq6Q": "パスワードで保護されたPDFも圧縮できますか？",
    "pdfCompress.guide.faq6A": "パスワードがかかっているファイルは、事前に「PDFロック解除」ツールで解除してからアップロードしてください。",

