    "imageToPdf.successMsg": "PDFドキュメントが正常に生成されました！",
    "imageToPdf.reorderTip": "▲ / ▼ ボタンでページ順を簡単に並び替えることができます。",
    "imageToPdf.guide.title": "画像 PDF 変換完全ガイド",
    "imageToPdf.guide.badge": "100% 完全無料 & ローカル変換",
    "imageToPdf.guide.aboutTitle": "画像 PDF 変換ツールとは？",
    "imageToPdf.guide.aboutDesc": "JPG、PNG、WebP、GIF、BMPなどの複数画像を、サーバーへアップロードすることなくブラウザ内で順番通りに結合し、綺麗なA4規格などのPDFファイルとして出力できる安全な無料ツールです。",
    "imageToPdf.guide.howTitle": "画像をPDFに変換する方法",
    "imageToPdf.guide.step1": "PDFにまとめたい写真、領収書、スキャン書類を一括でドラッグ＆ドロップして選択します。",
    "imageToPdf.guide.step2": "矢印ボタン（▲/▼）でページの並び順を整え、用紙サイズ（A4、Letter、Fit）や余白を設定します。",
    "imageToPdf.guide.step3": "「PDFに一括変換する」をクリックし、わずか1秒で生成されたPDFをダウンロードします。",
    "imageToPdf.guide.featuresTitle": "画像 PDF 変換ツールの主な特徴",
    "imageToPdf.guide.feat1Title": "複数画像の一括高速マージ",
    "imageToPdf.guide.feat1Desc": "数十〜数百枚の写真を一度に読み込み、順番通りの1つのPDFドキュメントに瞬時にまとめます。",
    "imageToPdf.guide.feat2Title": "規格用紙＆画像ピッタリ配置",
    "imageToPdf.guide.feat2Desc": "ビジネス提出用のA4/Letterサイズ（余白調整可）から、写真比率を100%保つFitモードまで柔軟に対応。",
    "imageToPdf.guide.feat3Title": "ワンクリック順序入れ替え",
    "imageToPdf.guide.feat3Desc": "画像カードの上/下矢印をクリックするだけで、表紙・本文・添付資料の並び順を直感的に整理可能。",
    "imageToPdf.guide.feat4Title": "完全ローカル・プライベート処理",
    "imageToPdf.guide.feat4Desc": "プライベート写真や機密書類が外部サーバーへ送信されることはなく、ブラウザ内(Canvas/pdf-lib)で安全に完結します。",
    "imageToPdf.guide.useCasesTitle": "ビジネス・日常での代表的な活用例",
    "imageToPdf.guide.uc1Title": "領収書・請求書・経費精算書の作成",
    "imageToPdf.guide.uc1Desc": "スマホで撮影した複数のレシートや領収書写真を1つの整った提出用PDFにまとめて経理に提出。",
    "imageToPdf.guide.uc2Title": "身分証明書・各種証明書の提出",
    "imageToPdf.guide.uc2Desc": "運転免許証、マイナンバーカード、資格証明書の写真をA4サイズの綺麗な電子書類にして送信。",
    "imageToPdf.guide.uc3Title": "ポートフォリオ・作品集・ルックブック",
    "imageToPdf.guide.uc3Desc": "デザイン案、イラスト、写真作品を高画質なPDFカタログに仕立ててクライアントや面接官に共有。",
    "imageToPdf.guide.uc4Title": "スマホ撮影書類・講義ノートの電子化",
    "imageToPdf.guide.uc4Desc": "参考書のページやホワイトボード、手書きノートの写真を1冊の電子ブックPDFとして保存・アーカイブ。",
    "imageToPdf.guide.tipsTitle": "知っておくと便利なプロの活用ヒント",
    "imageToPdf.guide.tip1": "公的機関や会社への提出には、「A4標準」＋「標準余白」を選択すると印刷・閲覧時に最も美しく仕上がります。",
    "imageToPdf.guide.tip2": "余白のない写真集アルバムを作りたい場合は、「用紙サイズ: 画像に合わせる(Fit)」＋「余白なし」がおすすめです。",
    "imageToPdf.guide.tip3": "変換前に上(▲)・下(▼)ボタンでリストの並び順を確認しておくと、思い通りのページ構成になります。",
    "imageToPdf.guide.faqTitle": "よくある質問 (FAQ)",
    "imageToPdf.guide.faq1Q": "写真や書類データがサーバーに保存されますか？",
    "imageToPdf.guide.faq1A": "一切保存されません！すべての画像処理とPDF生成は、お使いの端末のブラウザメモリ内だけで100%ローカル実行されます。",
    "imageToPdf.guide.faq2Q": "JPG、PNG以外の画像フォーマットも変換できますか？",
    "imageToPdf.guide.faq2A": "はい！JPG、PNGをはじめ、最新のWebP、GIF、BMPなどブラウザが表示できるあらゆる画像形式に対応しています。",
    "imageToPdf.guide.faq3Q": "一度に何枚まで画像を変換できますか？",
    "imageToPdf.guide.faq3A": "制限はありません。お使いの端末のメモリが許す限り、数十〜数百枚の画像を自由に束ねて変換可能です。",
    "imageToPdf.guide.faq4Q": "A4サイズに変換したときに画像が歪んだり切れたりしませんか？",
    "imageToPdf.guide.faq4A": "いいえ！画像の元のアスペクト比（縦横比）を100%維持したまま、指定した余白内にぴったり綺麗に自動配置されます。",
    "imageToPdf.guide.faq5Q": "出力されるPDFのファイル容量を小さくしたい場合は？",
    "imageToPdf.guide.faq5A": "設定パネルで「画像画質・圧縮」を「高圧縮」または「標準最適化」に指定すると軽量なPDFが作成されます。",
    "imageToPdf.guide.faq6Q": "スマホ（iPhone/Android）やiPadでも使えますか？",
    "imageToPdf.guide.faq6A": "はい！モバイル端末に完全対応しており、SafariやChromeなどのモバイルブラウザから直接ご利用いただけます。",

    // PDF Protect (Encrypt)
