    "pdfProtect.resetBtn": "別のPDFを暗号化",
    "pdfProtect.guide.title": "PDF パスワード設定＆セキュリティ暗号化完全ガイド",
    "pdfProtect.guide.badge": "100% 完全無料 & ブラウザ内暗号化",
    "pdfProtect.guide.aboutTitle": "PDF パスワード設定ツールとは？",
    "pdfProtect.guide.aboutDesc": "desktools.runのPDF暗号化ツールは、WebCryptoおよびpdf-libを活用し、ブラウザ内で100%ローカルに国際標準のPDF AES暗号化を施します。パスワードや機密データがサーバーへ送信されることは一切なく、極めて安全です。",
    "pdfProtect.guide.howTitle": "PDFにパスワードを設定する方法",
    "pdfProtect.guide.step1": "パスワードで保護したいPDFドキュメントをドラッグ＆ドロップで選択します。",
    "pdfProtect.guide.step2": "閲覧に必要なパスワードを入力し、確認欄にもう一度入力します。",
    "pdfProtect.guide.step3": "「PDFを暗号化してダウンロード」をクリックすると、1秒で暗号化済みPDFが生成されます。",
    "pdfProtect.guide.featuresTitle": "PDF パスワード設定ツールの主な特徴",
    "pdfProtect.guide.feat1Title": "完全ローカル・クライアント暗号化",
    "pdfProtect.guide.feat1Desc": "すべての暗号化処理が端末メモリ内で実行されるため、機密契約書や個人情報が外部へ漏洩するリスクはありません。",
    "pdfProtect.guide.feat2Title": "国際標準のPDF暗号化規格",
    "pdfProtect.guide.feat2Desc": "Adobe Acrobat、Chrome、Safari、スマホのPDFリーダーなど、世界中の標準ビューアーと100%互換性があります。",
    "pdfProtect.guide.feat3Title": "リアルタイムパスワード強度診断",
    "pdfProtect.guide.feat3Desc": "文字数、大文字小文字、数字、記号の組み合わせをリアルタイムで解析し、強固なパスワード設定をサポート。",
    "pdfProtect.guide.feat4Title": "レイアウト・ベクター品質の無損失維持",
    "pdfProtect.guide.feat4Desc": "暗号化保護レイヤーを追加するのみで、元のテキストの鮮明さや画像解像度は100%そのまま保持されます。",
    "pdfProtect.guide.useCasesTitle": "ビジネス・日常での代表的な活用例",
    "pdfProtect.guide.uc1Title": "雇用契約書・給与明細書の安全送信",
    "pdfProtect.guide.uc1Desc": "従業員の給与明細や人事書類にパスワードを掛け、メール誤送信時の情報漏洩を防止。",
    "pdfProtect.guide.uc2Title": "財務諸表・決算書類・税務データの保護",
    "pdfProtect.guide.uc2Desc": "企業の決算報告書や監査資料を暗号化し、関係者のみが閲覧できるように安全にロック。",
    "pdfProtect.guide.uc3Title": "秘密保持契約(NDA)・特許出願書類の共有",
    "pdfProtect.guide.uc3Desc": "企業間のNDA契約書や特許資料、企画書を外部パートナーと安全に共有。",
    "pdfProtect.guide.uc4Title": "身分証コピー・医療診断書の保護",
    "pdfProtect.guide.uc4Desc": "マイナンバーカードやパスポートスキャン、診断書など極秘の個人情報書類を保護。",
    "pdfProtect.guide.tipsTitle": "パスワード設定時のセキュリティヒント",
    "pdfProtect.guide.tip1": "英大文字・小文字、数字、記号を組み合わせた8文字以上のパスワードを設定することを推奨します。",
    "pdfProtect.guide.tip2": "相手に送る際は、ファイル送信（メール）とパスワード伝達（チャットやSMS）の手段を分けると安全です。",
    "pdfProtect.guide.tip3": "標準暗号化の仕様上、パスワードを紛失すると復元できません。必ず安全な場所にメモ・保管してください。",
    "pdfProtect.guide.faqTitle": "よくある質問 (FAQ)",
    "pdfProtect.guide.faq1Q": "ファイルやパスワードがサーバーに送信されますか？",
    "pdfProtect.guide.faq1A": "一切送信されません！すべての暗号化処理はブラウザのWebCryptoエンジン内で100%ローカル実行されます。",
    "pdfProtect.guide.faq2Q": "暗号化されたPDFはどのアプリで開けますか？",
    "pdfProtect.guide.faq2A": "Adobe Acrobat Reader、Chrome、Edge、Safari、スマートフォン標準のPDFビューアーなど、世界中のあらゆるPDFリーダーでパスワードを入力して開けます。",
    "pdfProtect.guide.faq3Q": "パスワードを忘れた場合、復元できますか？",
    "pdfProtect.guide.faq3A": "いいえ。標準の暗号化仕様により、パスワードがないと作成者であっても解除できません。大切に管理してください。",
    "pdfProtect.guide.faq4Q": "暗号化できるファイルサイズに制限はありますか？",
    "pdfProtect.guide.faq4A": "制限はありません。お使いの端末メモリが許す限り、大容量のPDFでも無料で暗号化できます。",
    "pdfProtect.guide.faq5Q": "暗号化すると文字や画像の画質は落ちますか？",
    "pdfProtect.guide.faq5A": "いいえ！暗号化レイヤーを追加するだけなので、元のテキスト、ベクター、画像品質は100%劣化しません。",
    "pdfProtect.guide.faq6Q": "後からパスワードを解除したい場合は？",
    "pdfProtect.guide.faq6A": "当サイトの「PDF パスワード解除」ツールでパスワードを1回入力すれば、通常のPDFに戻して保存できます。",

