    "pdfUnlock.guide.faq6Q": "iPhoneやAndroidスマホでも使えますか？",
    "pdfUnlock.guide.faq6A": "はい！SafariやChromeなど、すべてのモバイルブラウザからアプリ不要で直接快適にご利用いただけます。",

