    "pdfMerger.remove": "Eliminar",
    "pdfMerger.pages": "páginas",
    "pdfMerger.guide.title": "Guía Completa para Combinar PDFs",
    "pdfMerger.guide.badge": "100% Gratis y Procesamiento Local",
    "pdfMerger.guide.aboutTitle": "¿Qué es la herramienta de unir PDFs?",
    "pdfMerger.guide.aboutDesc": "Permite organizar y unir varios archivos PDF en un solo documento 100% dentro de la memoria de tu navegador, sin subir ningún archivo a servidores externos.",
    "pdfMerger.guide.howTitle": "Cómo Unir Archivos PDF",
    "pdfMerger.guide.step1": "Arrastra y suelta o selecciona varios archivos PDF para cargar.",
    "pdfMerger.guide.step2": "Usa los botones arriba (▲) y abajo (▼) para ordenar los archivos en la secuencia que prefieras.",
    "pdfMerger.guide.step3": "Introduce un nombre de archivo personalizado y haz clic en 'Unir PDFs' para descargarlo al instante.",
    "pdfMerger.guide.featuresTitle": "Características y Ventajas Principales",
    "pdfMerger.guide.feat1Title": "Privacidad 100% en el Navegador",
    "pdfMerger.guide.feat1Desc": "Todo el procesamiento ocurre localmente en la memoria de tu navegador. Los documentos confidenciales nunca tocan servidores externos.",
    "pdfMerger.guide.feat2Title": "Preservación Vectorial y de Texto Sin Pérdida",
    "pdfMerger.guide.feat2Desc": "Conserva la selección de texto nativa, capacidad de búsqueda, fuentes, gráficos vectoriales e hipervínculos sin degradación.",
    "pdfMerger.guide.feat3Title": "Sin Límite de Tamaño ni de Archivos",
    "pdfMerger.guide.feat3Desc": "Sin muros de pago ni cuotas diarias. Une tantos archivos y páginas PDF como permita la memoria de tu dispositivo.",
    "pdfMerger.guide.feat4Title": "Compatibilidad Universal Multiplataforma",
    "pdfMerger.guide.feat4Desc": "Funciona al instante en Windows, macOS, Linux, iPad y navegadores móviles sin necesidad de instalar software.",
    "pdfMerger.guide.useCasesTitle": "Casos de Uso Populares y Escenarios",
    "pdfMerger.guide.uc1Title": "Propuestas Comerciales e Informes",
    "pdfMerger.guide.uc1Desc": "Consolida planes de proyectos, actas de reuniones, contratos y presupuestos en un único documento profesional.",
    "pdfMerger.guide.uc2Title": "Candidaturas Laborales y Portafolios",
    "pdfMerger.guide.uc2Desc": "Une tu currículum, carta de presentación, muestras de trabajo y certificados en un solo PDF listo para enviar.",
    "pdfMerger.guide.uc3Title": "Artículos Académicos y Diapositivas",
    "pdfMerger.guide.uc3Desc": "Organiza apuntes de clase, artículos de investigación y capítulos de libros electrónicos en un documento de estudio unificado.",
    "pdfMerger.guide.uc4Title": "Facturas y Recibos de Gastos",
    "pdfMerger.guide.uc4Desc": "Agrupa facturas mensuales y recibos de gastos en orden cronológico para facilitar la contabilidad.",
    "pdfMerger.guide.tipsTitle": "Consejos Profesionales para Unir PDFs",
    "pdfMerger.guide.tip1": "Para PDFs protegidos con contraseña, desbloquéalos primero con nuestra herramienta de desbloqueo de PDF antes de unirlos.",
    "pdfMerger.guide.tip2": "Diferentes tamaños de página (A4, Carta, A3) y orientaciones (Vertical/Horizontal) se mantienen sin problemas.",
    "pdfMerger.guide.tip3": "Verifica el orden de la portada, índice y anexos con los botones arriba/abajo antes de descargar.",
    "pdfMerger.guide.faqTitle": "Preguntas Frecuentes (FAQ)",
    "pdfMerger.guide.faq1Q": "¿Mis archivos PDF se suben o guardan en algún servidor?",
    "pdfMerger.guide.faq1A": "No. Todo el análisis y la unión de páginas ocurren 100% de forma local en tu navegador con WebAssembly y pdf-lib. Nada se envía a servidores.",
    "pdfMerger.guide.faq2Q": "¿El PDF unido conservará el texto buscable, fuentes y enlaces?",
    "pdfMerger.guide.faq2A": "¡Sí! Unimos objetos binarios nativos de PDF en lugar de aplanar imágenes. El texto seleccionable, fuentes y URLs se mantienen intactos.",
    "pdfMerger.guide.faq3Q": "¿Hay límite en la cantidad de PDFs o páginas que puedo unir?",
    "pdfMerger.guide.faq3A": "No hay ningún límite artificial. Puedes unir tantos archivos como permita la memoria RAM de tu ordenador o teléfono.",
    "pdfMerger.guide.faq4Q": "¿Puedo unir PDFs con diferentes tamaños de página y orientaciones?",
    "pdfMerger.guide.faq4A": "Sí, cada página conserva sus dimensiones originales (A4, Carta, etc.) y su orientación vertical u horizontal.",
    "pdfMerger.guide.faq5Q": "¿Cómo reorganizo los archivos antes de unir?",
    "pdfMerger.guide.faq5A": "Tras cargarlos, pulsa los botones Arriba (▲) y Abajo (▼) en cada tarjeta para ordenarlos como desees.",
    "pdfMerger.guide.faq6Q": "¿Funciona en teléfonos móviles y tabletas?",
    "pdfMerger.guide.faq6A": "¡Sí! La herramienta es totalmente responsive y compatible con Chrome, Safari y navegadores móviles modernos.",
