    "pdfSplit.guide.title": "Guía Completa para Dividir y Extraer Páginas de PDF",
    "pdfSplit.guide.badge": "100% Gratis y Procesamiento Local",
    "pdfSplit.guide.aboutTitle": "¿Qué es la herramienta de Dividir PDF?",
    "pdfSplit.guide.aboutDesc": "Dividir PDF es una utilidad 100% gratuita y local que te permite extraer páginas individuales, separar documentos en archivos de una página o extraer rangos personalizados directamente en la memoria de tu navegador (pdf-lib) sin subir nada al servidor.",
    "pdfSplit.guide.howTitle": "Cómo Dividir y Extraer Páginas de un PDF",
    "pdfSplit.guide.step1": "Arrastra y suelta o selecciona el archivo PDF que deseas dividir.",
    "pdfSplit.guide.step2": "Selecciona el modo de división: todas las páginas, rango personalizado (ej. 1-3, 5) o selección visual por miniaturas.",
    "pdfSplit.guide.step3": "Haz clic en 'Dividir PDF Ahora' y descarga tus archivos inmediatamente.",
    "pdfSplit.guide.featuresTitle": "Características y Ventajas Principales",
    "pdfSplit.guide.feat1Title": "Privacidad 100% en el Navegador",
    "pdfSplit.guide.feat1Desc": "Toda la división se ejecuta localmente en la memoria de tu dispositivo. Los contratos confidenciales y datos personales nunca tocan servidores externos.",
    "pdfSplit.guide.feat2Title": "Miniaturas Visuales Interactivas",
    "pdfSplit.guide.feat2Desc": "Previsualiza cada página renderizada en miniatura y selecciona exactamente las que necesitas con un simple clic.",
    "pdfSplit.guide.feat3Title": "3 Modos Flexibles de División",
    "pdfSplit.guide.feat3Desc": "Soporte para división de una página por archivo, rangos complejos (ej. 1-3, 5, 8-12) y selección visual directa.",
    "pdfSplit.guide.feat4Title": "Preservación Vectorial y OCR Sin Pérdida",
    "pdfSplit.guide.feat4Desc": "Extrae objetos binarios nativos del PDF conservando el texto seleccionable, fuentes, vectores y enlaces con total nitidez.",
    "pdfSplit.guide.useCasesTitle": "Casos de Uso Populares y Escenarios",
    "pdfSplit.guide.uc1Title": "Extraer Páginas Concretas para Envío",
    "pdfSplit.guide.uc1Desc": "Separa únicamente las páginas de firma, certificados o anexos requeridos de un contrato extenso.",
    "pdfSplit.guide.uc2Title": "Dividir Capítulos de Libros y Artículos",
    "pdfSplit.guide.uc2Desc": "Organiza capítulos de libros de texto, tesis o artículos científicos en archivos individuales fáciles de consultar.",
    "pdfSplit.guide.uc3Title": "Eliminar Páginas Internas Confidenciales",
    "pdfSplit.guide.uc3Desc": "Excluye tarifas internas, datos privados o notas confidenciales antes de compartir un documento externamente.",
    "pdfSplit.guide.uc4Title": "Separar Lotes Escaneados en Páginas Sueltas",
    "pdfSplit.guide.uc4Desc": "Convierte documentos escaneados en lote en archivos individuales de una página para archivado digital.",
    "pdfSplit.guide.tipsTitle": "Consejos Profesionales para Dividir PDFs",
    "pdfSplit.guide.tip1": "Combina comas y guiones como '1-3, 5, 8-12' en el modo de rango para extraer múltiples secciones no consecutivas a la vez.",
    "pdfSplit.guide.tip2": "En el modo visual, pulsa 'Seleccionar Todo' y desmarca las pocas páginas que no quieras para ahorrar tiempo.",
    "pdfSplit.guide.tip3": "¿Necesitas unir las páginas extraídas con otros documentos? Usa después nuestra herramienta 'Unir PDFs'.",
    "pdfSplit.guide.faqTitle": "Preguntas Frecuentes (FAQ)",
    "pdfSplit.guide.faq1Q": "¿Es seguro dividir documentos PDF confidenciales?",
    "pdfSplit.guide.faq1A": "¡Sí, totalmente seguro! Todo el procesamiento se realiza de forma local en la memoria de tu navegador (pdf-lib), sin que tus archivos se envíen a ningún servidor externo.",
    "pdfSplit.guide.faq2Q": "¿Puedo extraer páginas no consecutivas como la 1, 3 y 5?",
    "pdfSplit.guide.faq2A": "Sí. Puedes escribir '1, 3, 5' en el rango personalizado o marcar las miniaturas que desees para agruparlas y extraerlas en un nuevo PDF.",
    "pdfSplit.guide.faq3Q": "¿El PDF extraído conservará el texto buscable, fuentes y enlaces?",
    "pdfSplit.guide.faq3A": "¡Sí! Extraemos la estructura nativa del PDF en lugar de simples capturas, conservando la selección de texto, fuentes y nitidez original.",
    "pdfSplit.guide.faq4Q": "¿Hay algún límite de páginas o de tamaño de archivo?",
    "pdfSplit.guide.faq4A": "No hay límites artificiales. Puedes dividir archivos PDF de cualquier tamaño siempre que la memoria RAM de tu equipo lo soporte.",
    "pdfSplit.guide.faq5Q": "¿Cómo se nombran los archivos al usar 'Dividir todas las páginas'?",
    "pdfSplit.guide.faq5A": "Cada página se exporta limpiamente como '[nombre]_page_1.pdf', '[nombre]_page_2.pdf', etc.",
    "pdfSplit.guide.faq6Q": "¿Puedo dividir un archivo PDF protegido por contraseña?",
    "pdfSplit.guide.faq6A": "Desbloquea el archivo primero con nuestra herramienta de desbloqueo de PDF antes de cargarlo para dividirlo.",
