    "pdfCompress.guide.title": "Guía Completa para Reducir y Comprimir PDFs",
    "pdfCompress.guide.badge": "100% Gratis y Procesamiento Local",
    "pdfCompress.guide.aboutTitle": "¿Qué es la herramienta de Compresión PDF?",
    "pdfCompress.guide.aboutDesc": "Comprime y optimiza estructuras binarias de objetos y metadatos internos directamente en la memoria de tu navegador (pdf-lib) sin subir nada a servidores externos, ofreciendo total privacidad y rapidez.",
    "pdfCompress.guide.howTitle": "Cómo Reducir el Tamaño de un PDF",
    "pdfCompress.guide.step1": "Arrastra y suelta o selecciona el documento PDF que deseas comprimir.",
    "pdfCompress.guide.step2": "Elige el nivel de compresión deseado (Recomendado, Alta Compresión o Baja Compresión).",
    "pdfCompress.guide.step3": "Haz clic en 'Comprimir PDF Ahora' y descarga tu archivo optimizado al instante.",
    "pdfCompress.guide.featuresTitle": "Características y Ventajas Principales",
    "pdfCompress.guide.feat1Title": "Privacidad 100% en el Navegador",
    "pdfCompress.guide.feat1Desc": "Toda la optimización se ejecuta localmente en tu equipo. Los contratos confidenciales y datos personales nunca salen de tu dispositivo.",
    "pdfCompress.guide.feat2Title": "3 Niveles de Compresión Personalizados",
    "pdfCompress.guide.feat2Desc": "Elige entre Recomendado (equilibrio), Alta (máximo ahorro) o Baja (máxima calidad) según tus necesidades.",
    "pdfCompress.guide.feat3Title": "Medidor de Ahorro en Tiempo Real",
    "pdfCompress.guide.feat3Desc": "Comprueba al instante el tamaño original vs. comprimido y el porcentaje de reducción antes de descargar.",
    "pdfCompress.guide.feat4Title": "Preserva la Nitidez de Textos y Vectores",
    "pdfCompress.guide.feat4Desc": "Limpia flujos binarios redundantes manteniendo intacta la nitidez de tipografías, vectores y búsqueda OCR.",
    "pdfCompress.guide.useCasesTitle": "Casos de Uso Populares y Cotidianos",
    "pdfCompress.guide.uc1Title": "Límites de Archivos Adjuntos en Email",
    "pdfCompress.guide.uc1Desc": "Reduce documentos voluminosos por debajo de 10MB/25MB para enviarlos fácilmente por Gmail, Outlook o servidores corporativos.",
    "pdfCompress.guide.uc2Title": "Portales Oficiales y Empleo",
    "pdfCompress.guide.uc2Desc": "Ajusta tus archivos a los límites estrictos de subida (2MB-5MB) en portales gubernamentales y bolsas de empleo.",
    "pdfCompress.guide.uc3Title": "Ahorro de Espacio Móvil y Nube",
    "pdfCompress.guide.uc3Desc": "Ahorra valiosos gigabytes en Google Drive, Dropbox, iCloud o en la memoria de tu smartphone optimizando tus documentos.",
    "pdfCompress.guide.uc4Title": "Aligerar Libros y Presentaciones",
    "pdfCompress.guide.uc4Desc": "Comprime diapositivas extensas, informes anuales y libros digitales para una lectura ágil en móviles.",
    "pdfCompress.guide.tipsTitle": "Consejos Profesionales para Comprimir PDFs",
    "pdfCompress.guide.tip1": "Para informes estándar de oficina, el modo 'Recomendado' ofrece el mejor balance sin pérdida visual.",
    "pdfCompress.guide.tip2": "Si el PDF contiene cientos de páginas escaneadas en alta resolución, 'Alta Compresión' logra reducciones espectaculares.",
    "pdfCompress.guide.tip3": "¿Vas a unir varios archivos antes de enviarlos? Únelos primero con 'Unir PDFs' y comprime el resultado final.",
    "pdfCompress.guide.faqTitle": "Preguntas Frecuentes (FAQ)",
    "pdfCompress.guide.faq1Q": "¿Mis documentos PDF se suben a algún servidor externo?",
    "pdfCompress.guide.faq1A": "¡No! Todo el procesamiento y compresión se ejecutan 100% de forma local en la memoria de tu navegador. Nada se sube a internet.",
    "pdfCompress.guide.faq2Q": "¿Comprimir el archivo hará que el texto se vuelva borroso?",
    "pdfCompress.guide.faq2A": "No. El texto vectorial, fuentes del sistema y maquetación se conservan totalmente nítidos y con búsqueda de texto intacta.",
    "pdfCompress.guide.faq3Q": "¿Existe algún límite de tamaño o de páginas?",
    "pdfCompress.guide.faq3A": "No hay límites artificiales. Puedes comprimir documentos grandes de forma gratuita siempre que la RAM de tu equipo lo permita.",
    "pdfCompress.guide.faq4Q": "¿Por qué algunos PDFs reducen muy poco su tamaño?",
    "pdfCompress.guide.faq4A": "Los archivos que solo contienen texto o que ya fueron optimizados previamente tienen menos flujos redundantes para recortar.",
    "pdfCompress.guide.faq5Q": "¿Cuál es la diferencia entre compresión Recomendada y Alta?",
    "pdfCompress.guide.faq5A": "Recomendada optimiza estructuras internas sin diferencias visuales. Alta compresión realiza un reempaquetado más agresivo.",
    "pdfCompress.guide.faq6Q": "¿Puedo comprimir un PDF protegido con contraseña?",
    "pdfCompress.guide.faq6A": "Por favor, desbloquea el archivo primero con nuestra herramienta 'Desbloquear PDF' antes de comprimirlo.",

