    "imageToPdf.guide.aboutDesc": "Es una utilidad gratuita y privada que combina fotos en formatos JPG, PNG, WebP, GIF y BMP en un único documento PDF elegante y ordenado sin enviar ningún dato a servidores externos.",
    "imageToPdf.guide.howTitle": "Cómo Convertir Imágenes a PDF",
    "imageToPdf.guide.step1": "Arrastra y suelta o selecciona todas las fotos, recibos o documentos escaneados que desees unir.",
    "imageToPdf.guide.step2": "Reordena las páginas con los botones de flecha y configura el formato de papel (A4, Letter, Fit) y márgenes.",
    "imageToPdf.guide.step3": "Haz clic en 'Convertir a Documento PDF' y descarga de inmediato tu archivo PDF final.",
    "imageToPdf.guide.featuresTitle": "Características Principales",
    "imageToPdf.guide.feat1Title": "Conversión por Lotes de Múltiples Imágenes",
    "imageToPdf.guide.feat1Desc": "Carga decenas o cientos de imágenes al mismo tiempo y combínalas secuencialmente en un único PDF.",
    "imageToPdf.guide.feat2Title": "Formatos Estándar y Ajuste Automático",
    "imageToPdf.guide.feat2Desc": "Elige tamaños A4/Letter con márgenes ajustables, o adapta el documento a la proporción exacta de las imágenes.",
    "imageToPdf.guide.feat3Title": "Reordenación Rápida de Páginas",
    "imageToPdf.guide.feat3Desc": "Ajusta fácilmente el orden de portadas, cuerpo y anexos con los botones de flecha arriba y abajo.",
    "imageToPdf.guide.feat4Title": "100% Privado en el Navegador",
    "imageToPdf.guide.feat4Desc": "Todo el ensamblaje se procesa en la memoria local de tu navegador mediante Canvas y WebAssembly.",
    "imageToPdf.guide.useCasesTitle": "Casos de Uso Cotidianos y Prácticos",
    "imageToPdf.guide.uc1Title": "Informes de Gastos y Facturas",
    "imageToPdf.guide.uc1Desc": "Reúne fotos de recibos de compra, facturas y tickets en un solo PDF ordenado para contabilidad.",
    "imageToPdf.guide.uc2Title": "Envío de Documentos de Identidad y Títulos",
    "imageToPdf.guide.uc2Desc": "Agrupa fotos de DNI/cédula, pasaportes y diplomas en un archivo PDF A4 listo para trámites oficiales.",
    "imageToPdf.guide.uc3Title": "Portafolios Fotográficos y Catálogos",
    "imageToPdf.guide.uc3Desc": "Presenta diseños, fotografías o catálogos de productos en un formato PDF de alta fidelidad para clientes.",
    "imageToPdf.guide.uc4Title": "Digitalización de Apuntes y Libros",
    "imageToPdf.guide.uc4Desc": "Convierte fotos de páginas de libros, pizarras o contratos tomadas con tu móvil en un PDF paginado.",
    "imageToPdf.guide.tipsTitle": "Consejos Profesionales",
    "imageToPdf.guide.tip1": "Para trámites formales, selecciona 'A4 Estándar' con 'Margen Normal' para obtener un aspecto impecable.",
    "imageToPdf.guide.tip2": "Para crear un álbum de fotos sin bordes blancos, selecciona 'Ajustar a Imagen (Fit)' y 'Sin Margen'.",
    "imageToPdf.guide.tip3": "Comprueba el orden de la lista con los botones ▲ y ▼ antes de generar el documento.",
    "imageToPdf.guide.faqTitle": "Preguntas Frecuentes (FAQ)",
    "imageToPdf.guide.faq1Q": "¿Mis fotos privadas se suben a algún servidor?",
    "imageToPdf.guide.faq1A": "¡Nunca! Todo el procesamiento se realiza localmente en la memoria de tu navegador.",
    "imageToPdf.guide.faq2Q": "¿Qué formatos de imagen son compatibles?",
    "imageToPdf.guide.faq2A": "Soporta JPG, JPEG, PNG, WebP, GIF y BMP sin necesidad de conversión previa.",
    "imageToPdf.guide.faq3Q": "¿Cuántas imágenes puedo convertir a la vez?",
    "imageToPdf.guide.faq3A": "No hay límite artificial. Puedes unir tantas imágenes como permita la memoria RAM de tu equipo.",
    "imageToPdf.guide.faq4Q": "¿Se recortarán o deformarán mis fotos?",
    "imageToPdf.guide.faq4A": "No. Las imágenes siempre conservan su relación de aspecto original y se escalan proporcionalmente.",
    "imageToPdf.guide.faq5Q": "¿Cómo puedo reducir el peso del PDF final?",
    "imageToPdf.guide.faq5A": "Selecciona 'Alta Compresión' u 'Optimizado' en los ajustes de calidad antes de realizar la conversión.",
    "imageToPdf.guide.faq6Q": "¿Puedo usarlo en iPhone, Android o tabletas?",
    "imageToPdf.guide.faq6A": "¡Sí! La herramienta funciona de forma totalmente fluida en navegadores móviles como Safari y Chrome.",

