    "pdfProtect.guide.title": "Guía Completa de Protección y Cifrado de PDF con Contraseña",
    "pdfProtect.guide.badge": "100% Gratis y Cifrado Local",
    "pdfProtect.guide.aboutTitle": "¿Qué es la herramienta de Proteger PDF?",
    "pdfProtect.guide.aboutDesc": "Aplica cifrado estándar AES a tus documentos PDF directamente en la memoria de tu navegador (WebCrypto y pdf-lib) sin transmitir tu contraseña ni tus archivos a servidores externos, garantizando máxima privacidad.",
    "pdfProtect.guide.howTitle": "Cómo Proteger un Archivo PDF con Contraseña",
    "pdfProtect.guide.step1": "Arrastra y suelta o selecciona el documento PDF que deseas bloquear.",
    "pdfProtect.guide.step2": "Escribe la contraseña de apertura y repítela en el campo de confirmación.",
    "pdfProtect.guide.step3": "Haz clic en 'Cifrar PDF y Descargar' para recibir instantáneamente tu archivo protegido.",
    "pdfProtect.guide.featuresTitle": "Características Principales de Seguridad",
    "pdfProtect.guide.feat1Title": "Privacidad 100% en el Dispositivo",
    "pdfProtect.guide.feat1Desc": "Toda la criptografía se ejecuta en el navegador. Los contratos privados y secretos comerciales nunca viajan por internet.",
    "pdfProtect.guide.feat2Title": "Cifrado Estándar Compatible Globalmente",
    "pdfProtect.guide.feat2Desc": "Compatible con Adobe Acrobat Reader, Chrome, Safari, Apple Vista Previa y todos los lectores PDF del mundo.",
    "pdfProtect.guide.feat3Title": "Medidor de Fortaleza de Contraseña",
    "pdfProtect.guide.feat3Desc": "Evalúa en tiempo real la robustez de tu clave con indicadores visuales de longitud, números y símbolos.",
    "pdfProtect.guide.feat4Title": "Conservación Vectorial y de Imagen Sin Pérdidas",
    "pdfProtect.guide.feat4Desc": "Agrega la capa de seguridad sin alterar la nitidez del texto, fuentes vectoriales ni la resolución gráfica.",
    "pdfProtect.guide.useCasesTitle": "Casos de Uso Populares y Cotidianos",
    "pdfProtect.guide.uc1Title": "Contratos Laborales y Nóminas Salariales",
    "pdfProtect.guide.uc1Desc": "Protege recibos de nómina y contratos de personal antes de enviarlos por correo electrónico.",
    "pdfProtect.guide.uc2Title": "Estados Financieros e Informes Fiscales",
    "pdfProtect.guide.uc2Desc": "Bloquea balances contables y declaraciones de impuestos para acceso exclusivo de auditores y directivos.",
    "pdfProtect.guide.uc3Title": "Acuerdos de Confidencialidad (NDA) y Patentes",
    "pdfProtect.guide.uc3Desc": "Comparte planes estratégicos y acuerdos confidenciales con socios externos con total tranquilidad.",
    "pdfProtect.guide.uc4Title": "Documentos de Identidad e Historiales Médicos",
    "pdfProtect.guide.uc4Desc": "Evita el acceso no autorizado a pasaportes escaneados, diagnósticos médicos y certificados familiares.",
    "pdfProtect.guide.tipsTitle": "Consejos Profesionales de Seguridad",
    "pdfProtect.guide.tip1": "Combina letras mayúsculas, minúsculas, números y símbolos (8+ caracteres) para una protección óptima.",
    "pdfProtect.guide.tip2": "Envía el documento y la contraseña por canales separados (ej. documento por correo, clave por SMS/WhatsApp).",
    "pdfProtect.guide.tip3": "Guarda la contraseña en un gestor seguro; por seguridad criptográfica, si se pierde no se puede recuperar.",
    "pdfProtect.guide.faqTitle": "Preguntas Frecuentes (FAQ)",
    "pdfProtect.guide.faq1Q": "¿Mi contraseña o archivo PDF se envían a algún servidor?",
    "pdfProtect.guide.faq1A": "¡No! Todas las operaciones de cifrado se ejecutan 100% en la memoria de tu navegador. Ningún dato sale de tu equipo.",
    "pdfProtect.guide.faq2Q": "¿Con qué visores se puede abrir el PDF protegido?",
    "pdfProtect.guide.faq2A": "Con cualquier lector PDF estándar (Adobe Acrobat, Chrome, Safari, Edge, visores móviles de Android/iOS) introduciendo la clave.",
    "pdfProtect.guide.faq3Q": "¿Puedo recuperar el PDF si olvido la contraseña?",
    "pdfProtect.guide.faq3A": "No. El cifrado estándar no tiene puertas traseras. Asegúrate de anotar o guardar la contraseña de forma segura.",
    "pdfProtect.guide.faq4Q": "¿Existe límite de tamaño de archivo para cifrar?",
    "pdfProtect.guide.faq4A": "No hay límites artificiales. Puedes cifrar archivos grandes siempre que la memoria RAM de tu equipo lo permita.",
    "pdfProtect.guide.faq5Q": "¿El cifrado reduce la calidad del texto o de las fotos?",
    "pdfProtect.guide.faq5A": "No. Solo se añade una capa de seguridad criptográfica; el contenido y la calidad visual quedan 100% intactos.",
    "pdfProtect.guide.faq6Q": "¿Cómo puedo quitar la contraseña más adelante?",
    "pdfProtect.guide.faq6A": "Puedes usar nuestra herramienta 'Desbloquear PDF' en cualquier momento ingresando la clave para guardarlo sin contraseña.",

