    "pdfMerger.guide.title": "PDF 合并完整指南",
    "pdfMerger.guide.badge": "100% 免费 & 浏览器本地处理",
    "pdfMerger.guide.aboutTitle": "什么是 PDF 合并工具？",
    "pdfMerger.guide.aboutDesc": "无需上传服务器，100% 在您的浏览器内存中安全、无损地将多个 PDF 文档按指定顺序合并为一个完整的文档。",
    "pdfMerger.guide.howTitle": "如何合并 PDF 文件",
    "pdfMerger.guide.step1": "拖放或选择多个要合并的 PDF 文件进行上传。",
    "pdfMerger.guide.step2": "使用列表中的上移(▲)和下移(▼)按钮调整文件的合并顺序。",
    "pdfMerger.guide.step3": "输入自定义文件名，点击“合并 PDF 文件”按钮即可立即下载。",
    "pdfMerger.guide.featuresTitle": "PDF 合并工具核心优势与特点",
    "pdfMerger.guide.feat1Title": "100% 客户端隐私安全",
    "pdfMerger.guide.feat1Desc": "所有 PDF 处理均在您本地浏览器内存中完成，机密商业文档与个人隐私数据绝不上传服务器。",
    "pdfMerger.guide.feat2Title": "无损矢量与文本保留",
    "pdfMerger.guide.feat2Desc": "采用原生 PDF 二进制对象合并技术而非简单截屏，完美保留文本可选复制、搜索、字体及超链接。",
    "pdfMerger.guide.feat3Title": "文件数量与大小无人工限制",
    "pdfMerger.guide.feat3Desc": "无任何每日次数限制或付费门槛，只要您的设备内存允许，可一次合并数十个大文件。",
    "pdfMerger.guide.feat4Title": "全平台设备即开即用",
    "pdfMerger.guide.feat4Desc": "无需安装任何软件或插件，兼容 Windows、macOS、Linux、iPad 以及手机移动端浏览器。",
    "pdfMerger.guide.useCasesTitle": "常见应用场景与用例",
    "pdfMerger.guide.uc1Title": "商务提案与报告汇总",
    "pdfMerger.guide.uc1Desc": "将分散编制的项目方案、会议纪要、合同附件及报价单整合为一份规整的汇报文档。",
    "pdfMerger.guide.uc2Title": "求职简历 · 作品集 · 证明文件",
    "pdfMerger.guide.uc2Desc": "求职应聘或提交政府机构时，将个人简历、自荐信、证书扫描件及作品集打包成统一 PDF。",
    "pdfMerger.guide.uc3Title": "课程讲义 · 学术论文 · 电子书",
    "pdfMerger.guide.uc3Desc": "整理按周分发的教学课件、期刊论文各章节或电子书 PDF，归档为一本完整的电子材料。",
    "pdfMerger.guide.uc4Title": "电子发票与报销凭证整理",
    "pdfMerger.guide.uc4Desc": "按月份或项目将电子增值税发票与费用报销单据按日期排序合并，方便财务归档与审计。",
    "pdfMerger.guide.tipsTitle": "专家实用小技巧",
    "pdfMerger.guide.tip1": "对于设置了密码的 PDF，建议先使用我们的“PDF 解锁”工具去除密码后再进行合并。",
    "pdfMerger.guide.tip2": "不同页面尺寸（A4、Letter、A3）或横纵方向混排时，各页面均会保留原始版面规格。",
    "pdfMerger.guide.tip3": "点击下载前，可通过卡片右侧的上移/下移箭头仔细检查封面、目录与正文的先后次序。",
    "pdfMerger.guide.faqTitle": "常见问题解答 (FAQ)",
    "pdfMerger.guide.faq1Q": "我的 PDF 文件会被上传或保存到服务器吗？",
    "pdfMerger.guide.faq1A": "不会。desktools.run 的所有处理均通过 WebAssembly 及 pdf-lib 引擎在您的浏览器本地完成，关闭页面即刻销毁。",
    "pdfMerger.guide.faq2Q": "合并后的 PDF 依然可以进行文本搜索和复制吗？",
    "pdfMerger.guide.faq2A": "是的！我们保留了原生 PDF 二进制结构，文字选取、关键词检索、嵌入字体及超链接完全不受影响。",
    "pdfMerger.guide.faq3Q": "合并的文件数量或页数有限制吗？",
    "pdfMerger.guide.faq3A": "没有人工限制。只要您计算机或手机的浏览器内存充足，支持一次性合并多个大体量文档。",
    "pdfMerger.guide.faq4Q": "页面尺寸不同（如 A4 与 Letter）或横纵混排可以合并吗？",
    "pdfMerger.guide.faq4A": "完全可以。每个页面都会独立保持其原始尺寸和旋转方向，自然拼合为一个统一文件。",
    "pdfMerger.guide.faq5Q": "合并前如何调整文件的先后顺序？",
    "pdfMerger.guide.faq5A": "上传文件后，点击每个文件卡片右侧的“上移(▲)”与“下移(▼)”按钮即可任意调整顺序。",
    "pdfMerger.guide.faq6Q": "支持在智能手机或平板电脑上使用吗？",
    "pdfMerger.guide.faq6A": "支持！本工具完全适配移动端，在 Chrome、Safari、微信内置浏览器等均可顺畅运行。",
