    "pdfSplit.guide.faq6Q": "可以拆分带有密码保护的 PDF 文件吗？",
    "pdfSplit.guide.faq6A": "加密的 PDF 请先使用我们的“PDF 解锁”工具去除密码，然后再上传进行拆分。",
