    "pdfCompress.guide.badge": "100% 免费 & 浏览器本地处理",
    "pdfCompress.guide.aboutTitle": "什么是 PDF 压缩工具？",
    "pdfCompress.guide.aboutDesc": "本工具利用浏览器本地内存（pdf-lib）重组并优化 PDF 内部对象数据流与冗余元数据，全程不上传远程服务器，以极快速度实现私密、安全的文档体积缩减。",
