    "pdfCompress.guide.useCasesTitle": "常见应用场景与用例",
    "pdfCompress.guide.uc1Title": "解决邮件超大附件限制",
    "pdfCompress.guide.uc1Desc": "将体积臃肿的 PDF 轻松降至 10MB/25MB 限制以下，确保通过企业邮箱、Gmail、QQ 邮箱顺利发送。",
    "pdfCompress.guide.uc2Title": "政府政务与招聘网站材料提交",
    "pdfCompress.guide.uc2Desc": "完美适配各大招聘系统、高校申研系统、政务服务平台对上传附件 2MB-5MB 的严格大小限制。",
    "pdfCompress.guide.uc3Title": "节省手机与云盘存储空间",
    "pdfCompress.guide.uc3Desc": "对日常归档的 PDF 电子文档批量精简，释放百度网盘、iCloud、手机相册的宝贵存储空间。",
    "pdfCompress.guide.uc4Title": "精简课件、电子书与年报文件",
    "pdfCompress.guide.uc4Desc": "将包含大量插图的高清 PPT 导出件或电子教材体积减半，提升移动端翻阅与分发速度。",
    "pdfCompress.guide.tipsTitle": "专家实用小技巧",
    "pdfCompress.guide.tip1": "对于常规的办公公文或文字报告，默认的“推荐压缩”即可实现零画质损失的极佳瘦身效果。",
    "pdfCompress.guide.tip2": "若文档包含数百页高分辨率扫描图，“强力压缩”能够带来极为惊人的体积缩减比例。",
    "pdfCompress.guide.tip3": "若需汇总多份文件提交，建议先使用“PDF 合并”工具整合成一份，最后再统一执行压缩。",
    "pdfCompress.guide.faqTitle": "常见问题解答 (FAQ)",
    "pdfCompress.guide.faq1Q": "我上传的 PDF 文件会被传送到远程服务器吗？",
    "pdfCompress.guide.faq1A": "不会！所有压缩与数据流优化都在您的本地浏览器内存（pdf-lib）中完成，任何数据都不会离开您的设备。",
    "pdfCompress.guide.faq2Q": "压缩后 PDF 中的文字会变模糊或失真吗？",
    "pdfCompress.guide.faq2A": "不会！文字为矢量字体结构，压缩后字迹依然保持原版清晰度，文本复制与关键词搜索（OCR）完全不受影响。",
    "pdfCompress.guide.faq3Q": "有文件体积或页数上限吗？",
    "pdfCompress.guide.faq3A": "没有人工限制。只要您设备的运行内存充足，即使是数百页的大体量文档也可以免费极速处理。",
    "pdfCompress.guide.faq4Q": "为什么有些 PDF 压缩后体积变化不明显？",
    "pdfCompress.guide.faq4A": "如果 PDF 之前已经被其他工具深度优化过，或者纯为轻量文本构成，则可进一步精简的二进制冗余流较少。",
    "pdfCompress.guide.faq5Q": "“推荐压缩”与“强力压缩”有何不同？",
    "pdfCompress.guide.faq5A": "推荐压缩侧重无损精简内部对象结构；强力压缩则会采用更深度的重编码策略以换取最大程度的存储节省。",
    "pdfCompress.guide.faq6Q": "可以压缩带有密码保护的 PDF 文件吗？",
    "pdfCompress.guide.faq6A": "加密文件请先使用我们的“PDF 解锁”工具去除密码，然后再上传进行压缩。",

