    "pdfProtect.guide.tip2": "向他人分发文件时，建议将文档发送渠道（如邮件）与密码告知渠道（如微信/短信）分开。",
    "pdfProtect.guide.tip3": "根据标准加密特性，如果遗忘密码将无法找回或破解，请务必妥善记录并保管好密码。",
