    "pdfProtect.guide.faq1Q": "我设置的密码或上传的 PDF 会被发送到服务器吗？",
    "pdfProtect.guide.faq1A": "绝不会！所有加密计算均在您本地浏览器的 WebCrypto 引擎中进行，没有任何密码或文档数据离开您的设备。",
