    "pdfProtect.guide.faq3A": "不能。标准加密机制不存在后门，即使作者本人遗忘也无法恢复，请务必将密码备份在安全的地方。",
    "pdfProtect.guide.faq4Q": "对加密的 PDF 文件大小有限制吗？",
