    "pdfProtect.guide.faq5A": "完全不会！加密仅在二进制层添加密码安全保护，文档内部的文字、矢量字体与图片画质 100% 原样保留。",
    "pdfProtect.guide.faq6Q": "以后如果想永久取消密码该怎么做？",
