    "pdfMerger.guide.title": "Guide Complet de Fusion PDF",
    "pdfMerger.guide.badge": "100% Gratuit & Traitement Local",
    "pdfMerger.guide.aboutTitle": "Qu'est-ce que l'outil de fusion PDF ?",
    "pdfMerger.guide.aboutDesc": "Permet de regrouper plusieurs fichiers PDF en un seul document organisé 100% dans la mémoire de votre navigateur, sans aucun téléversement de fichier sur un serveur.",
    "pdfMerger.guide.howTitle": "Comment fusionner des fichiers PDF",
    "pdfMerger.guide.step1": "Glissez-déposez ou sélectionnez plusieurs fichiers PDF à charger.",
    "pdfMerger.guide.step2": "Utilisez les boutons Monter (▲) et Descendre (▼) pour organiser les fichiers dans l'ordre souhaité.",
    "pdfMerger.guide.step3": "Indiquez un nom de fichier personnalisé et cliquez sur 'Fusionner les PDF' pour le télécharger instantanément.",
    "pdfMerger.guide.featuresTitle": "Points forts et fonctionnalités clés",
    "pdfMerger.guide.feat1Title": "Confidentialité 100% côté client",
    "pdfMerger.guide.feat1Desc": "Toutes les opérations s'exécutent localement dans la mémoire du navigateur. Vos documents confidentiels ne quittent jamais votre appareil.",
    "pdfMerger.guide.feat2Title": "Préservation vectorielle et textuelle sans perte",
    "pdfMerger.guide.feat2Desc": "Conserve la sélection de texte native, la recherche, les polices intégrées, les graphismes vectoriels et les hyperliens.",
    "pdfMerger.guide.feat3Title": "Zéro limite de taille ou de nombre de fichiers",
    "pdfMerger.guide.feat3Desc": "Aucun quota quotidien ni abonnement payant. Fusionnez autant de documents que la mémoire de votre appareil le permet.",
    "pdfMerger.guide.feat4Title": "Compatibilité universelle multiplateforme",
    "pdfMerger.guide.feat4Desc": "Fonctionne instantanément sur Windows, macOS, Linux, iPad et navigateurs mobiles sans aucun logiciel à installer.",
    "pdfMerger.guide.useCasesTitle": "Cas d'usage et scénarios populaires",
    "pdfMerger.guide.uc1Title": "Propositions commerciales et rapports",
    "pdfMerger.guide.uc1Desc": "Regroupez plans de projet, comptes-rendus de réunion, contrats et devis en un document officiel unique.",
    "pdfMerger.guide.uc2Title": "Candidatures et portfolios",
    "pdfMerger.guide.uc2Desc": "Assemblez CV, lettre de motivation, attestations et portfolio en un seul PDF prêt à l'envoi.",
    "pdfMerger.guide.uc3Title": "Notes de cours, thèses et livres numériques",
    "pdfMerger.guide.uc3Desc": "Organisez les diapositives de cours, articles scientifiques et chapitres de livres en un seul document d'étude.",
    "pdfMerger.guide.uc4Title": "Factures et reçus de dépenses",
    "pdfMerger.guide.uc4Desc": "Classez vos factures mensuelles et justificatifs de frais par ordre chronologique pour la comptabilité.",
    "pdfMerger.guide.tipsTitle": "Astuces de pros pour fusionner vos PDF",
    "pdfMerger.guide.tip1": "Pour les PDF protégés par mot de passe, déverrouillez-les d'abord avec notre outil Déverrouiller PDF.",
    "pdfMerger.guide.tip2": "Les différents formats de page (A4, Letter, A3) et orientations (Portrait/Paysage) sont conservés à l'identique.",
    "pdfMerger.guide.tip3": "Vérifiez l'ordre de la couverture, du sommaire et des annexes à l'aide des flèches avant de lancer le téléchargement.",
    "pdfMerger.guide.faqTitle": "Foire Aux Questions (FAQ)",
    "pdfMerger.guide.faq1Q": "Mes fichiers PDF sont-ils envoyés ou stockés sur un serveur ?",
    "pdfMerger.guide.faq1A": "Non. Tout le traitement et la fusion s'effectuent à 100% localement dans votre navigateur grâce à WebAssembly et pdf-lib.",
    "pdfMerger.guide.faq2Q": "Le PDF fusionné conserve-t-il le texte recherchable et les liens ?",
    "pdfMerger.guide.faq2A": "Oui ! Nous fusionnons la structure binaire native du PDF sans aplatir en image. Le texte, les polices et les URLs restent intacts.",
    "pdfMerger.guide.faq3Q": "Y a-t-il une limite sur le nombre de fichiers ou de pages ?",
    "pdfMerger.guide.faq3A": "Aucune limite artificielle. Vous pouvez fusionner autant de fichiers que la mémoire RAM de votre appareil le permet.",
    "pdfMerger.guide.faq4Q": "Puis-je fusionner des PDF avec des formats ou orientations différents ?",
    "pdfMerger.guide.faq4A": "Oui, chaque page conserve ses dimensions d'origine (A4, Letter, etc.) et son orientation portrait ou paysage.",
    "pdfMerger.guide.faq5Q": "Comment réorganiser les fichiers avant la fusion ?",
    "pdfMerger.guide.faq5A": "Après le chargement, cliquez sur les boutons Monter (▲) et Descendre (▼) sur chaque carte de fichier pour ajuster l'ordre.",
    "pdfMerger.guide.faq6Q": "L'outil fonctionne-t-il sur smartphone et tablette ?",
    "pdfMerger.guide.faq6A": "Oui ! L'outil est entièrement responsive et compatible avec Chrome, Safari et tous les navigateurs mobiles modernes.",
