    "pdfSplit.guide.badge": "100% Gratuit & Traitement Local",
    "pdfSplit.guide.aboutTitle": "Qu'est-ce que l'outil de division PDF ?",
    "pdfSplit.guide.aboutDesc": "Le diviseur de PDF est un utilitaire 100% gratuit et local permettant d'extraire des pages individuelles, de séparer des documents en fichiers d'une page ou d'extraire des plages personnalisées directement dans la mémoire de votre navigateur (pdf-lib) en toute sécurité.",
    "pdfSplit.guide.howTitle": "Comment diviser et extraire des pages PDF",
    "pdfSplit.guide.step1": "Glissez-déposez ou sélectionnez le fichier PDF que vous souhaitez diviser.",
    "pdfSplit.guide.step2": "Choisissez le mode de division : toutes les pages, plage personnalisée (ex. 1-3, 5) ou sélection visuelle par vignettes.",
