    "pdfSplit.guide.feat4Title": "Préservation vectorielle et OCR sans perte",
    "pdfSplit.guide.feat4Desc": "Extrait les objets binaires natifs du PDF : la sélection de texte, les polices intégrées, les graphismes vectoriels et les liens restent parfaits.",
    "pdfSplit.guide.useCasesTitle": "Cas d'usage et scénarios populaires",
    "pdfSplit.guide.uc1Title": "Extraire des pages précises pour transmission",
    "pdfSplit.guide.uc1Desc": "Isolez uniquement les pages de signature, certificats ou annexes d'un contrat volumineux pour envoi ciblé.",
    "pdfSplit.guide.uc2Title": "Scinder chapitres de livres et thèses",
    "pdfSplit.guide.uc2Desc": "Découpez un manuel d'étude volumineux ou des publications académiques en chapitres autonomes faciles à consulter.",
    "pdfSplit.guide.uc3Title": "Supprimer des pages confidentielles",
    "pdfSplit.guide.uc3Desc": "Excluez les grilles tarifaires internes, données personnelles ou brouillons avant de partager un document avec l'extérieur.",
    "pdfSplit.guide.uc4Title": "Organiser des lots numérisés en pages individuelles",
    "pdfSplit.guide.uc4Desc": "Transformez les numérisations en bloc de votre copieur en fichiers PDF individuels d'une seule page pour archivage.",
    "pdfSplit.guide.tipsTitle": "Astuces de pros pour découper vos PDF",
    "pdfSplit.guide.tip1": "Combinez virgules et tirets (ex. '1-3, 5, 8-12') dans le mode plage pour extraire plusieurs sections non consécutives à la fois.",
    "pdfSplit.guide.tip2": "En mode visuel, cliquez sur 'Tout sélectionner' puis décochez les quelques pages indésirables pour gagner du temps.",
    "pdfSplit.guide.tip3": "Besoin de réassembler les pages extraites avec d'autres fichiers ? Utilisez ensuite notre outil 'Fusionner des PDF'.",
    "pdfSplit.guide.faqTitle": "Foire Aux Questions (FAQ)",
    "pdfSplit.guide.faq1Q": "Est-il sûr de diviser des documents PDF contenant des données sensibles ?",
    "pdfSplit.guide.faq1A": "Oui, tout à fait sûr ! L'intégralité du traitement s'effectue localement dans la mémoire de votre navigateur (pdf-lib) sans qu'aucun fichier ne soit transféré vers un serveur.",
    "pdfSplit.guide.faq2Q": "Puis-je extraire des pages non consécutives comme les pages 1, 3 et 5 ?",
    "pdfSplit.guide.faq2A": "Oui. Vous pouvez saisir '1, 3, 5' dans le champ de saisie personnalisé ou cocher les vignettes de votre choix pour les regrouper dans un nouveau PDF.",
    "pdfSplit.guide.faq3Q": "Le PDF extrait conserve-t-il le texte recherchable et les polices ?",
    "pdfSplit.guide.faq3A": "Oui ! Nous extrayons la structure native du PDF sans convertir en image, ce qui garantit la recherche de texte et une netteté vectorielle absolue.",
    "pdfSplit.guide.faq4Q": "Existe-t-il une limite de taille ou de nombre de pages ?",
