    "pdfSplit.guide.faq6Q": "Puis-je diviser un fichier PDF protégé par mot de passe ?",
    "pdfSplit.guide.faq6A": "Veuillez d'abord déverrouiller le fichier avec notre outil Déverrouiller PDF avant de le charger pour le diviser.",
