    "pdfCompress.guide.title": "Guide Complet pour Réduire et Compresser un PDF",
    "pdfCompress.guide.badge": "100% Gratuit & Traitement Local",
    "pdfCompress.guide.aboutTitle": "Qu'est-ce que l'outil de compression PDF ?",
    "pdfCompress.guide.aboutDesc": "L'outil optimise les flux d'objets binaires et les métadonnées internes directement dans la mémoire de votre navigateur (pdf-lib) sans aucun transfert de fichier, garantissant une réduction rapide et 100% confidentielle.",
    "pdfCompress.guide.howTitle": "Comment Réduire la Taille d'un Fichier PDF",
    "pdfCompress.guide.step1": "Glissez-déposez ou sélectionnez le fichier PDF que vous souhaitez compresser.",
    "pdfCompress.guide.step2": "Choisissez le niveau de compression adapté (Recommandé, Haute Compression ou Faible Compression).",
    "pdfCompress.guide.step3": "Cliquez sur 'Compresser le PDF Maintenant' et téléchargez instantanément votre document allégé.",
    "pdfCompress.guide.featuresTitle": "Points Forts et Fonctionnalités Clés",
    "pdfCompress.guide.feat1Title": "Confidentialité 100% Côté Client",
    "pdfCompress.guide.feat1Desc": "Toute l'optimisation s'exécute dans la mémoire de votre navigateur. Vos contrats et documents confidentiels ne quittent jamais votre appareil.",
    "pdfCompress.guide.feat2Title": "3 Niveaux de Compression Dédiés",
    "pdfCompress.guide.feat2Desc": "Choisissez entre Recommandé (équilibré), Haute (gain maximal) et Faible (fidélité maximale) selon vos besoins.",
    "pdfCompress.guide.feat3Title": "Indicateur d'Économie en Temps Réel",
    "pdfCompress.guide.feat3Desc": "Visualisez immédiatement la taille initiale, la taille finale et le pourcentage exact d'espace économisé avant le téléchargement.",
    "pdfCompress.guide.feat4Title": "Préservation de la Netteté Vectorielle et Texte",
    "pdfCompress.guide.feat4Desc": "Nettoie les flux binaires superflus tout en conservant les polices, les graphismes vectoriels et la recherche de texte (OCR).",
    "pdfCompress.guide.useCasesTitle": "Cas d'Usage et Scénarios Populaires",
    "pdfCompress.guide.uc1Title": "Limites de Pièces Jointes par E-mail",
    "pdfCompress.guide.uc1Desc": "Réduisez vos PDF sous les seuils de 10 Mo / 25 Mo pour un envoi fluide sur Gmail, Outlook ou vos boîtes professionnelles.",
    "pdfCompress.guide.uc2Title": "Portails Administratifs et Recrutement",
    "pdfCompress.guide.uc2Desc": "Respectez les limites strictes d'envoi (2 Mo à 5 Mo) sur les plateformes de candidature et les portails publics.",
    "pdfCompress.guide.uc3Title": "Gain d'Espace Mobile et Cloud",
    "pdfCompress.guide.uc3Desc": "Libérez de précieux gigaoctets sur Google Drive, Dropbox, iCloud ou votre smartphone en allégeant vos archives PDF.",
    "pdfCompress.guide.uc4Title": "Alléger Livres Numériques et Rapports",
    "pdfCompress.guide.uc4Desc": "Rendez vos présentations volumineuses et documents illustrés beaucoup plus rapides à consulter sur mobile.",
    "pdfCompress.guide.tipsTitle": "Astuces de Pros pour Compresser vos PDF",
    "pdfCompress.guide.tip1": "Pour les documents de bureau courants, le mode 'Recommandé' offre le meilleur compromis sans perte visuelle.",
    "pdfCompress.guide.tip2": "Si le document contient de nombreux scans haute résolution, le mode 'Haute Compression' génère des gains spectaculaires.",
    "pdfCompress.guide.tip3": "Besoin de réunir plusieurs fichiers avant envoi ? Utilisez d'abord 'Fusionner des PDF' puis compressez le document final.",
    "pdfCompress.guide.faqTitle": "Foire Aux Questions (FAQ)",
    "pdfCompress.guide.faq1Q": "Mes fichiers PDF sont-ils envoyés vers un serveur externe ?",
    "pdfCompress.guide.faq1A": "Non ! L'intégralité du traitement s'exécute localement dans votre navigateur. Vos données ne sont jamais téléversées sur internet.",
    "pdfCompress.guide.faq2Q": "La compression rend-elle le texte flou ou illisible ?",
    "pdfCompress.guide.faq2A": "Non ! Le texte vectoriel et les polices système restent parfaitement nets et la fonction de recherche de texte est préservée.",
    "pdfCompress.guide.faq3Q": "Existe-t-il une limite de taille ou de nombre de pages ?",
    "pdfCompress.guide.faq3A": "Aucune limite artificielle. Vous pouvez compresser des documents volumineux tant que la mémoire RAM de votre appareil le permet.",
    "pdfCompress.guide.faq4Q": "Pourquoi certains fichiers ne réduisent-ils que très peu ?",
    "pdfCompress.guide.faq4A": "Les fichiers déjà optimisés ou composés uniquement de texte pur ont moins de flux de données redondants à supprimer.",
    "pdfCompress.guide.faq5Q": "Quelle est la différence entre compression Recommandée et Haute ?",
    "pdfCompress.guide.faq5A": "Recommandée optimise les structures internes sans différence visuelle. Haute compression applique un rééchantillonnage plus fort.",
    "pdfCompress.guide.faq6Q": "Puis-je compresser un fichier PDF protégé par mot de passe ?",
    "pdfCompress.guide.faq6A": "Veuillez d'abord déverrouiller le fichier avec notre outil Déverrouiller PDF avant de le compresser.",

