    "pdfProtect.guide.aboutTitle": "Qu'est-ce que l'outil de Protection PDF ?",
    "pdfProtect.guide.aboutDesc": "Cet outil applique un chiffrement AES standard directement dans la mémoire de votre navigateur via WebCrypto et pdf-lib. Vos mots de passe et documents ne sont jamais transmis à des serveurs tiers.",
    "pdfProtect.guide.howTitle": "Comment Protéger un PDF avec un Mot de Passe",
    "pdfProtect.guide.step1": "Glissez-déposez ou sélectionnez le fichier PDF que vous souhaitez verrouiller.",
    "pdfProtect.guide.step2": "Saisissez votre mot de passe d'ouverture et confirmez-le dans le second champ.",
    "pdfProtect.guide.step3": "Cliquez sur 'Chiffrer le PDF et Télécharger' pour récupérer instantanément votre document sécurisé.",
