    "pdfProtect.guide.uc1Title": "Contrats de Travail et Bulletins de Paie",
    "pdfProtect.guide.uc1Desc": "Protégez les fiches de salaire et documents RH avant envoi par courriel pour éviter les fuites de données.",
    "pdfProtect.guide.uc2Title": "Bilans Financiers et Déclarations Fiscales",
    "pdfProtect.guide.uc2Desc": "Verrouillez les liasses fiscales et bilans comptables réservés aux auditeurs et à la direction.",
    "pdfProtect.guide.uc3Title": "Accords de Confidentialité (NDA) et Brevets",
    "pdfProtect.guide.uc3Desc": "Partagez des projets stratégiques et accords industriels avec vos partenaires en toute sérénité.",
    "pdfProtect.guide.uc4Title": "Pièces d'Identité et Dossiers Médicaux",
    "pdfProtect.guide.uc4Desc": "Empêchez la consultation non autorisée de passeports scannés, ordonnances et attestations d'assurance.",
    "pdfProtect.guide.tipsTitle": "Conseils de Sécurité Utiles",
    "pdfProtect.guide.tip1": "Combinez majuscules, minuscules, chiffres et caractères spéciaux (8+ caractères) pour une protection maximale.",
    "pdfProtect.guide.tip2": "Transmettez le document et le mot de passe par des canaux distincts (ex. document par e-mail, code par SMS/Signal).",
    "pdfProtect.guide.tip3": "Notez bien le mot de passe dans un gestionnaire sécurisé : le chiffrement standard ne peut pas être récupéré en cas d'oubli.",
    "pdfProtect.guide.faqTitle": "Foire Aux Questions (FAQ)",
    "pdfProtect.guide.faq1Q": "Mon mot de passe ou document est-il envoyé sur un serveur ?",
    "pdfProtect.guide.faq1A": "Non ! Tous les algorithmes s'exécutent 100% localement dans votre navigateur. Aucune donnée ne quitte votre appareil.",
    "pdfProtect.guide.faq2Q": "Quels lecteurs peuvent ouvrir le fichier chiffré ?",
    "pdfProtect.guide.faq2A": "Tous les lecteurs PDF modernes (Adobe Acrobat, Chrome, Safari, Edge, visionneuses mobiles) en saisissant le mot de passe.",
    "pdfProtect.guide.faq3Q": "Puis-je récupérer le PDF si j'oublie le mot de passe ?",
    "pdfProtect.guide.faq3A": "Non. Le chiffrement standard est inviolable sans la clé légitime. Conservez précieusement votre mot de passe.",
    "pdfProtect.guide.faq4Q": "Y a-t-il une limite de taille de fichier ?",
    "pdfProtect.guide.faq4A": "Aucune limite artificielle. Vous pouvez chiffrer des fichiers volumineux tant que la mémoire RAM le permet.",
    "pdfProtect.guide.faq5Q": "Le chiffrement dégrade-t-il la qualité du document ?",
