    "pdfProtect.guide.faq6Q": "Comment retirer le mot de passe plus tard ?",
    "pdfProtect.guide.faq6A": "Vous pouvez utiliser notre outil 'Déverrouiller PDF' à tout moment en saisissant le mot de passe pour le réenregistrer sans protection.",

